def reverse_string(s):
    if not s:
        return ""

    l = list(s)
    n = len(l)

    for i in range(n // 2):
        temp = l[i]
        l[i] = l[n - 1 - i]
        l[n - 1 - i] = temp

    reversed_chars = []
    for j in l:
        reversed_chars.append(j)

    res = ""
    for k in reversed_chars:
        res += k

    temp_list = []
    for m in range(len(res)):
        temp_list.append(res[m])

    final_str = ""
    for p in temp_list:
        final_str += p

    return final_str

