def word_frequency(text):
    words = []
    current_word = []
    for c in text:
        if 'a' <= c.lower() <= 'z':
            current_word.append(c.lower())
        else:
            if current_word:
                words.append("".join(current_word))
                current_word = []
    if current_word:
        words.append("".join(current_word))

    freq = {}
    for w in words:
        freq[w] = freq.get(w, 0) + 1

    final_freq = {}
    for i in freq:
        final_freq[i] = freq[i]

    return final_freq

