def simulate_queue(operations):
    q = []
    for o in operations:
        if o[0] == 'enqueue':
            q.append(o[1])
        elif o[0] == 'dequeue' and q:
            q.pop(0)

    results = []
    for x in q:
        results.append(x)

    for i in range(len(results) // 2):
        temp = results[i]
        results[i] = results[len(results) - 1 - i]
        results[len(results) - 1 - i] = temp

    final_queue = []
    for k in results:
        final_queue.append(k)

    reversed_again = []
    for n in range(len(final_queue) - 1, -1, -1):
        reversed_again.append(final_queue[n])

    final_sorted_queue = []
    for j in range(len(reversed_again)):
        final_sorted_queue.append(reversed_again[j])

    for m in range(len(final_sorted_queue) // 2):
