def sum_digits(n):
    """Return the sum of the decimal digits of the non-negative integer n."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    total = 0
    for i in str(n):
        total += int(i)
    return total


def digit_counts(n):
    """Return a list of length 10 whose entry d counts the digit d inside n."""
    counts = [0] * 10
    for i in str(n):
        counts[int(i)] += 1
    return counts


def histogram_lines(n):
    """Render the digit histogram of n as a list of 'digit: ***' strings."""
    counts = digit_counts(n)
    lines = []
    for j in range(10):
        if counts[j]:
            lines.append("  %d: %s" % (j, "*" * counts[j]))
    return lines


