def seconds_to_hms(s):
    h = s // 3600
    m = (s % 3600) // 60
    e = s % 60

    parts = [h, m, e]
    formatted_parts = []
    for p in parts:
        g = str(p)
        if len(g) == 1:
            f = '0' + g
        else:
            f = g
        formatted_parts.append(f)

    result = []
    for i, t in enumerate(formatted_parts):
        result.append(t)
        if i < len(formatted_parts) - 1:
            result.append(':')

    final_string = ""
    for j in result:
        final_string += j

    return final_string

