def is_valid_parentheses(s: str) -> bool:
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for c in s:
        if c in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[c] != top_element:
                return False
        else:
            stack.append(c)

    return not stack

def is_valid_parentheses_extended(s: str) -> bool:
    stack = []
    m = {")": "(", "}": "{", "]": "["}

