def validate_shapes(matrix1, matrix2):
    """Raise ValueError unless both matrices have identical dimensions."""
    if len(matrix1) != len(matrix2):
        raise ValueError("row counts differ: %d vs %d" % (len(matrix1), len(matrix2)))
    for i in range(len(matrix1)):
        if len(matrix1[i]) != len(matrix2[i]):
            raise ValueError("row %d has widths %d and %d" % (i, len(matrix1[i]), len(matrix2[i])))


def matrix_subtract(matrix1, matrix2):
    """Return the element-wise difference matrix1 - matrix2."""
    validate_shapes(matrix1, matrix2)
    result_matrix = []
    for i in range(len(matrix1)):
        row = []
        for j in range(len(matrix1[i])):
            row.append(matrix1[i][j] - matrix2[i][j])
        result_matrix.append(row)
    return result_matrix


def format_number(value):
    """Render a number without a trailing '.0' for whole floats."""
    if isinstance(value, float) and value == int(value):
        return str(int(value))
    return str(value)


def column_widths(matrix):
    """Width in characters needed by each column when the matrix is printed."""
    widths = []
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            width = len(format_number(matrix[i][j]))
            if j == len(widths):
                widths.append(width)
            elif width > widths[j]:
                widths[j] = width
    return widths


def format_matrix(matrix):
    """Return the matrix as aligned text rows, one string per matrix row."""
    widths = column_widths(matrix)
    lines = []
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append(format_number(matrix[i][j]).rjust(widths[j]))
        lines.append("[ " + "  ".join(cells) + " ]")
    return lines


def report(matrix1, matrix2):
    """Print both operands, then their difference, in aligned blocks."""
    result_matrix = matrix_subtract(matrix1, matrix2)
    labels = ["A:", "B:", "A - B:"]
    blocks = [format_matrix(matrix1), format_matrix(matrix2), format_matrix(result_matrix)]
    for k in range(len(blocks)):
        print(labels[k])
        print("\n".join("   " + line for line in blocks[k]))
    return result_matrix


def main():
    cases = [
        ([[1, 2], [3, 4]], [[1, 1], [1, 1]]),
        ([[5, 0]], [[1, -1]]),
        ([[1.5, -2.0, 3], [0, 10, 7.25]], [[0.5, 2.0, 3], [-4, 10, 0.25]]),
    ]
    for i in range(len(cases)):
        matrix1, matrix2 = cases[i]
        print("case %d" % (i + 1))
        report(matrix1, matrix2)
        print("")


if __name__ == "__main__":
    main()

