import random


def simulate_dice_sum(num_dice):
    if not isinstance(num_dice, int) or isinstance(num_dice, bool):
        raise TypeError("num_dice must be an integer")
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")
    total_sum = 0
    for i in range(num_dice):
        total_sum += random.randint(1, 6)
    return total_sum


def roll_distribution(num_dice, trials):
    counts = {}
    for i in range(trials):
        total = simulate_dice_sum(num_dice)
        counts[total] = counts.get(total, 0) + 1
    return counts


def theoretical_counts(num_dice):
    ways = {0: 1}
    for i in range(num_dice):
        nxt = {}
        for total, count in ways.items():
            for j in range(1, 7):
                nxt[total + j] = nxt.get(total + j, 0) + count
        ways = nxt
    return ways


def format_histogram(counts, width=40):
    if not counts:
        return "(no rolls)"
    peak = max(counts.values())
    lines = []
    for total in range(min(counts), max(counts) + 1):
        hits = counts.get(total, 0)
        bars = width * hits // peak
        lines.append("%4d | %-*s %d" % (total, width, "#" * bars, hits))
    return "\n".join(lines)


def compare_to_theory(num_dice, trials):
    observed = roll_distribution(num_dice, trials)
    ways = theoretical_counts(num_dice)
    outcomes = 6 ** num_dice
    rows = []
    for total in sorted(ways):
        expected = trials * ways[total] / outcomes
        got = observed.get(total, 0)
        rows.append((total, got, expected, got - expected))
    return observed, rows


def main():
    for k in (1, 2):
        print("simulate_dice_sum(%d) -> %d" % (k, simulate_dice_sum(k)))
    print()

    trials = 6000
    for k in (2, 3):
        observed, rows = compare_to_theory(k, trials)
        print("%d dice, %d trials" % (k, trials))
        print(format_histogram(observed))
        print("%5s %8s %10s %8s" % ("sum", "observed", "expected", "diff"))
        for total, got, expected, diff in rows:
            print("%5d %8d %10.1f %8.1f" % (total, got, expected, diff))
        print()


if __name__ == "__main__":
    main()

