def validate_meeting(meeting):
    """Check that a meeting is a well formed (start, end) pair of ints."""
    if not isinstance(meeting, (tuple, list)) or len(meeting) != 2:
        raise ValueError("a meeting must be a (start_time, end_time) pair: %r" % (meeting,))
    start, end = meeting
    if isinstance(start, bool) or isinstance(end, bool):
        raise TypeError("meeting times must be integers: %r" % (meeting,))
    if not isinstance(start, int) or not isinstance(end, int):
        raise TypeError("meeting times must be integers: %r" % (meeting,))
    if start > end:
        raise ValueError("meeting starts after it ends: %r" % (meeting,))
    return (start, end)


def has_overlap(meeting1, meeting2):
    """Return True when the two meeting intervals share at least one instant."""
    start1, end1 = validate_meeting(meeting1)
    start2, end2 = validate_meeting(meeting2)
    return start1 < end2 and start2 < end1


def overlapping_pairs(meetings):
    """Return the indices of every pair of meetings that clash."""
    clashes = []
    for i in range(len(meetings)):
        for j in range(i + 1, len(meetings)):
            if has_overlap(meetings[i], meetings[j]):
                clashes.append((i, j))
    return clashes


def overlap_counts(meetings):
    """For each meeting, how many other meetings it collides with."""
    counts = []
    for i in range(len(meetings)):
        conflicts = 0
        for j in range(len(meetings)):
            if i != j and has_overlap(meetings[i], meetings[j]):
                conflicts += 1
        counts.append(conflicts)
    return counts


def merge_busy_intervals(meetings):
    """Collapse the meetings into the minimal list of busy intervals."""
    ordered = []
    for i in range(len(meetings)):
        ordered.append(validate_meeting(meetings[i]))
    ordered.sort()
    if not ordered:
        return []
    merged = [ordered[0]]
    for k in range(1, len(ordered)):
        start, end = ordered[k]
        last_start, last_end = merged[-1]
        if start <= last_end:
            merged[-1] = (last_start, max(last_end, end))
        else:
            merged.append((start, end))
    return merged


def schedule_report(meetings):
    """Build a human readable clash report for a day's meetings."""
    counts = overlap_counts(meetings)
    lines = []
    for i in range(len(meetings)):
        lines.append("#%d %s -> %d clash(es)" % (i, meetings[i], counts[i]))
    for i, j in overlapping_pairs(meetings):
        lines.append("clash: #%d %s with #%d %s" % (i, meetings[i], j, meetings[j]))
    busy = merge_busy_intervals(meetings)
    total = 0
    for start, end in busy:
        total += end - start
    lines.append("busy blocks: %s (%d minutes)" % (busy, total))
    return "\n".join(lines)


def main():
    examples = [((1, 5), (3, 7)), ((1, 2), (3, 4)), ((0, 10), (2, 3))]
    for first, second in examples:
        print("has_overlap(%s, %s) = %s" % (first, second, has_overlap(first, second)))
    day = [(9, 10), (9, 11), (10, 12), (13, 14), (13, 30)]
    print(schedule_report(day))


if __name__ == "__main__":
    main()

