    counts = overlap_counts(meetings)
    lines = []
    for index in range(len(meetings)):
        lines.append("#%d %s -> %d clash(es)" % (index, meetings[index], counts[index]))
    for index, column in overlapping_pairs(meetings):
        lines.append("clash: #%d %s with #%d %s" % (index, meetings[index], column, meetings[column]))
    busy = merge_busy_intervals(meetings)
    total = 0
    for start, end in busy:
        total += end - start
    lines.append("busy blocks: %s (%d minutes)" % (busy, total))
    return "\n".join(lines)


