def reverse_sentence_words(sentence):
    words = []
    current_word = []
    for c in sentence:
        if c == ' ':
            if current_word:
                words.append("".join(current_word))
                current_word = []
        else:
            current_word.append(c)
    if current_word:
        words.append("".join(current_word))

    reversed_words = [None] * len(words)
    w_len = len(words)
    for i in range(w_len):
        reversed_words[i] = words[w_len - 1 - i]

    result_parts = []
    for j in range(len(reversed_words)):
        result_parts.append(reversed_words[j])
        if j < len(reversed_words) - 1:
            result_parts.append(' ')

    return "".join(result_parts)

