def is_valid_ipv4(ip_address: str) -> bool:
    s = ip_address.split('.')
    if len(s) != 4:
        return False

    for c in ip_address:
        if not (c.isdigit() or c == '.'):
            return False

    for i in range(len(s)):
        if not s[i].isdigit():
            return False

    for j in s:
        if not (0 <= int(j) <= 255):
            return False
        if len(j) > 1 and j[0] == '0':
            return False

    l = [int(p) for p in s]
    for k in l:
        if not (0 <= k <= 255):
            return False

    t = ip_address.split('.')
    for n in t:
        if not n:
            return False

    for m in range(len(t)):
        if not t[m].isnumeric():
            return False

    return True

