def validate_2x2(matrix, name):
    if not isinstance(matrix, list) or len(matrix) != 2:
        raise ValueError(name + " must be a list of 2 rows")
    for i in range(2):
        row = matrix[i]
        if not isinstance(row, list) or len(row) != 2:
            raise ValueError(name + " row " + str(i) + " must have 2 entries")
        for j in range(2):
            value = row[j]
            if not isinstance(value, (int, float)) or isinstance(value, bool):
                raise ValueError(name + "[" + str(i) + "][" + str(j) + "] must be numeric")


def multiply_2x2_matrices(matrix_a, matrix_b):
    validate_2x2(matrix_a, "matrix_a")
    validate_2x2(matrix_b, "matrix_b")
    result = [[0, 0], [0, 0]]
    for i in range(2):
        for j in range(2):
            total = 0
            for k in range(2):
                total += matrix_a[i][k] * matrix_b[k][j]
            result[i][j] = total
    return result


def format_2x2(matrix):
    widths = [0, 0]
    for j in range(2):
        for i in range(2):
            widths[j] = max(widths[j], len(str(matrix[i][j])))
    lines = []
    for i in range(2):
        cells = []
        for j in range(2):
            cells.append(str(matrix[i][j]).rjust(widths[j]))
        lines.append("[ " + "  ".join(cells) + " ]")
    return "\n".join(lines)


