def validate_event(event):
    if not isinstance(event, tuple) or len(event) != 2:
        raise ValueError("an event must be a tuple of (start_time, end_time)")
    for i in range(2):
        if not isinstance(event[i], int) or isinstance(event[i], bool):
            raise ValueError("event times must be integers: %r" % (event,))
    if event[0] > event[1]:
        raise ValueError("event start must not be after its end: %r" % (event,))
    return event


def check_event_overlap(event1, event2):
    start1, end1 = validate_event(event1)
    start2, end2 = validate_event(event2)
    return start1 < end2 and start2 < end1


def find_overlapping_pairs(events):
    pairs = []
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if check_event_overlap(events[i], events[j]):
                pairs.append((i, j))
    return pairs


def merge_events(events):
    checked = []
    for i in range(len(events)):
        checked.append(validate_event(events[i]))
    ordered = sorted(checked)
    merged = []
    for k in range(len(ordered)):
        start, end = ordered[k]
        if merged and start <= merged[-1][1]:
            previous_start, previous_end = merged[-1]
            merged[-1] = (previous_start, max(previous_end, end))
        else:
            merged.append((start, end))
    return merged


def format_time(minutes):
    return "%02d:%02d" % (minutes // 60 % 24, minutes % 60)


def format_event(event):
    return "%s-%s" % (format_time(event[0]), format_time(event[1]))


def build_report(events):
    lines = ["Schedule (%d events):" % len(events)]
    for i in range(len(events)):
        lines.append("  [%d] %s" % (i, format_event(events[i])))
    conflicts = find_overlapping_pairs(events)
    if conflicts:
        lines.append("Conflicts:")
        for k in range(len(conflicts)):
            first, second = conflicts[k]
            lines.append("  [%d] %s overlaps [%d] %s"
                         % (first, format_event(events[first]),
                            second, format_event(events[second])))
    else:
        lines.append("Conflicts: none")
    blocks = merge_events(events)
    lines.append("Busy blocks:")
    for j in range(len(blocks)):
        lines.append("  " + format_event(blocks[j]))
    return "\n".join(lines)


def main():
    schedule = [(540, 600), (570, 630), (660, 720), (720, 780), (900, 915)]
    print(build_report(schedule))
    print(check_event_overlap((10, 20), (15, 25)))
    print(check_event_overlap((10, 15), (20, 25)))


if __name__ == "__main__":
    main()

