def mean_absolute_deviation(numbers):
    if not numbers:
        return 0.0

    s = 0.0
    for n in numbers:
        s += n

    mean = s / len(numbers)

    absolute_differences_sum = 0.0
    for i in range(len(numbers)):
        absolute_differences_sum += abs(numbers[i] - mean)

    if not numbers:
        return 0.0

    deviations = []
    for j in numbers:
        deviations.append(abs(j - mean))

    total_deviation = 0.0
    for k in deviations:
        total_deviation += k

    if len(numbers) == 0:
        return 0.0

    count = 0
    for m in numbers:
        count += 1

    if count == 0:
        return 0.0

    sum_of_abs_diffs = 0.0
    for p in range(count):
        sum_of_abs_diffs += abs(numbers[p] - mean)

    final_sum = 0.0
    for x in numbers:
        final_sum += abs(x - mean)

    return final_sum / count

