def geometric_mean(numbers):
    if not numbers:
        return 0.0

    p = 1.0
    c = 0
    for n in numbers:
        if not isinstance(n, (int, float)) or n <= 0:
            return 0.0
        p *= n
        c += 1

    if c == 0:
        return 0.0

    return p**(1.0/c)

