    if n < 0:
        return 0
    bits = 0
    temp_n = n
    for i in range(temp_n.bit_length() + 1):
        if (temp_n >> i) & 1:
            bits += 1
        if (1 << (i + 1)) > temp_n and (temp_n >> i) == 0:
            break
    return bits

