def _validate(label, r):
    if not isinstance(r, (tuple, list)) or len(r) != 2:
        raise ValueError("%s must be a (start, end) pair" % label)
    for i in range(2):
        if not isinstance(r[i], (int, float)) or isinstance(r[i], bool):
            raise TypeError("%s[%d] must be a number" % (label, i))
    if r[0] > r[1]:
        raise ValueError("%s has start greater than end" % label)
    return (r[0], r[1])


def range_overlap(range1, range2):
    """Return the overlapping part of two ranges, or None if they are disjoint."""
    a = _validate("range1", range1)
    b = _validate("range2", range2)
    start = max(a[0], b[0])
    end = min(a[1], b[1])
    if start > end:
        return None
    return (start, end)


def intersect_all(ranges):
    """Intersection common to every range in the sequence, or None."""
    if not ranges:
        return None
    current = _validate("ranges[0]", ranges[0])
    for i in range(1, len(ranges)):
        current = range_overlap(current, ranges[i])
        if current is None:
            return None
    return current


def overlap_matrix(ranges):
    """Pairwise overlaps, each entry holding two indices and their overlap."""
    pairs = []
    for i in range(len(ranges)):
        for j in range(i + 1, len(ranges)):
            pairs.append((i, j, range_overlap(ranges[i], ranges[j])))
    return pairs


def merge_ranges(ranges):
    """Collapse overlapping or touching ranges into a minimal sorted list."""
    clean = []
    for i in range(len(ranges)):
        clean.append(_validate("ranges[%d]" % i, ranges[i]))
    clean.sort()
    merged = []
    for i in range(len(clean)):
        start, end = clean[i]
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))
    return merged


def covered_length(ranges):
    """Total length of the union of the given ranges."""
    total = 0
    merged = merge_ranges(ranges)
    for i in range(len(merged)):
        total += merged[i][1] - merged[i][0]
    return total


def main():
    cases = [((1, 5), (3, 7)), ((1, 3), (5, 7)), ((0, 10), (2, 4)), ((1, 2), (2, 9))]
    for i in range(len(cases)):
        first, second = cases[i]
        print("case %d: %s & %s -> %s" % (i + 1, first, second, range_overlap(first, second)))

    group = [(1, 6), (4, 9), (2, 5), (20, 25)]
    print("group:", group)
    print("common to all:", intersect_all(group))
    for i, j, ov in overlap_matrix(group):
        print("  pair (%d,%d): %s" % (i, j, ov))
    print("merged:", merge_ranges(group))
    print("covered length:", covered_length(group))


if __name__ == "__main__":
    main()

