    if len(isbn) != 10:
        return False

    s = 0
    for i in range(9):
        c = isbn[i]
        if not c.isdigit():
            return False
        s += int(c) * (i + 1)

    last_char = isbn[9]
    if last_char.isdigit():
        s += int(last_char) * 10
    elif last_char == 'X':
        s += 10 * 10
    else:
