def justify_text_simple(words, max_width):
    lines = []
    current_line = []
    current_length = 0

    for w in words:
        if not current_line:
            current_line.append(w)
            current_length = len(w)
        elif current_length + 1 + len(w) <= max_width:
            current_line.append(w)
            current_length += 1 + len(w)
        else:
            lines.append(" ".join(current_line))
            current_line = [w]
            current_length = len(w)

    if current_line:
        lines.append(" ".join(current_line))

    justified_lines = []
    for m in lines:
        if " " not in m or len(m) == max_width:
            justified_lines.append(m)
        else:
            words_on_line = m.split(" ")
            num_words = len(words_on_line)
            total_spaces_needed = max_width - sum(len(x) for x in words_on_line)

            if num_words == 1:
                justified_lines.append(words_on_line[0])
                continue

            gaps = num_words - 1
            base_spaces = total_spaces_needed // gaps
            extra_spaces = total_spaces_needed % gaps

            line_parts = []
            for i in range(len(words_on_line)):
                line_parts.append(words_on_line[i])
                if i < gaps:
                    line_parts.append(" " * (base_spaces + (1 if i < extra_spaces else 0)))
            justified_lines.append("".join(line_parts))

    final_text = ""
    for k in justified_lines:
        if final_text:
            final_text += "\n"
        final_text += k

    return final_text

