    """Map each department name to the number of employees working in it."""
    counts = {}
    for index in range(len(db)):
        dept = db[index]['department']
        counts[dept] = counts.get(dept, 0) + 1
    return counts


def format_table(db):
    """Render the database as an aligned text table."""
    headers = ['ID', 'NAME', 'DEPARTMENT']
    rows = [headers]
    for index in range(len(db)):
        record = db[index]
        rows.append([str(record['id']), record['name'], record['department']])

    widths = []
    for column in range(len(headers)):
        widest = 0
        for index in range(len(rows)):
            if len(rows[index][column]) > widest:
                widest = len(rows[index][column])
        widths.append(widest)

    lines = []
    for index in range(len(rows)):
        cells = []
        for column in range(len(headers)):
            cells.append(rows[index][column].ljust(widths[column]))
        lines.append('  '.join(cells).rstrip())
    return '\n'.join(lines)


