def validate_interval(interval):
    if len(interval) != 2:
        raise ValueError("an interval needs exactly two endpoints: %r" % (interval,))
    for i in range(2):
        if not isinstance(interval[i], (int, float)) or isinstance(interval[i], bool):
            raise TypeError("endpoint %d is not a number: %r" % (i, interval[i]))
    if interval[0] > interval[1]:
        raise ValueError("start_time must not exceed end_time: %r" % (interval,))
    return tuple(interval)


def check_interval_overlap(interval1, interval2):
    a_start, a_end = validate_interval(interval1)
    b_start, b_end = validate_interval(interval2)
    return a_start <= b_end and b_start <= a_end


def overlap_length(interval1, interval2):
    if not check_interval_overlap(interval1, interval2):
        return 0
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    return end - start


def find_overlapping_pairs(intervals):
    pairs = []
    n = len(intervals)
    for i in range(n):
        for j in range(i + 1, n):
            if check_interval_overlap(intervals[i], intervals[j]):
                pairs.append((i, j))
    return pairs


def merge_intervals(intervals):
    ordered = sorted(validate_interval(iv) for iv in intervals)
    merged = []
    for current in ordered:
        if merged and check_interval_overlap(merged[-1], current):
            last = merged.pop()
            merged.append((last[0], max(last[1], current[1])))
        else:
            merged.append(current)
    return merged


def format_interval(interval):
    return "(%g, %g)" % (interval[0], interval[1])


def format_report(intervals):
    lines = []
    for i, interval in enumerate(intervals):
        lines.append("[%d] %s" % (i, format_interval(interval)))
    for i, j in find_overlapping_pairs(intervals):
        lines.append("overlap [%d]&[%d] of length %g" %
                     (i, j, overlap_length(intervals[i], intervals[j])))
    merged = merge_intervals(intervals)
    lines.append("merged: " + ", ".join(format_interval(iv) for iv in merged))
    return "\n".join(lines)


def main():
    samples = [((1, 5), (3, 7)), ((1, 5), (6, 10)), ((2, 2), (0, 2)), ((0, 10), (4, 6))]
    for first, second in samples:
        print("%s vs %s -> %s" % (format_interval(first), format_interval(second),
                                  check_interval_overlap(first, second)))
    schedule = [(9, 10.5), (10, 11), (12, 13), (12.5, 14), (15, 15)]
    print(format_report(schedule))


if __name__ == "__main__":
    main()

