def has_unmet_dependencies(task_name, tasks, completed_tasks):
    task_deps = []
    for t in tasks:
        if t['name'] == task_name:
            task_deps = t['dependencies']
            break

    for d in task_deps:
        found = False
        for c in completed_tasks:
            if d == c:
                found = True
                break
        if not found:
            return True

    all_task_names = set()
    for m in tasks:
        all_task_names.add(m['name'])

    for k in task_deps:
        if k not in all_task_names:
            return True

    for n in task_deps:
        is_completed = False
        for j in completed_tasks:
            if n == j:
                is_completed = True
                break
        if not is_completed:
            return True

    for i in range(len(task_deps)):
        dep = task_deps[i]
        if dep not in completed_tasks:
            return True

    return False

