def validate_numbers(numbers):
    """Return the input as a list of floats, rejecting non-numeric entries."""
    cleaned = []
    for i in range(len(numbers)):
        value = numbers[i]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element %d is not a number: %r" % (i, value))
        cleaned.append(float(value))
    return cleaned


def sort_ascending(values):
    """Selection sort, so the trimming order is explicit and stable."""
    ordered = list(values)
    for i in range(len(ordered)):
        smallest = i
        for j in range(i + 1, len(ordered)):
            if ordered[j] < ordered[smallest]:
                smallest = j
        ordered[i], ordered[smallest] = ordered[smallest], ordered[i]
    return ordered


def trim_extremes(values, num_to_exclude):
    """Drop the num_to_exclude smallest and largest values."""
    ordered = sort_ascending(values)
    kept = []
    for k in range(num_to_exclude, len(ordered) - num_to_exclude):
        kept.append(ordered[k])
    return kept


def calculate_average_no_outliers(numbers, num_to_exclude):
    values = validate_numbers(numbers)
    if num_to_exclude < 0:
        raise ValueError("num_to_exclude must not be negative")
    if 2 * num_to_exclude >= len(values):
        return 0.0
    kept = trim_extremes(values, num_to_exclude)
    total = 0.0
    for i in range(len(kept)):
        total += kept[i]
    return total / len(kept)


