def validate_numbers(numbers):
    """Return the input as a list of floats, rejecting non-numeric entries."""
    cleaned = []
    for index in range(len(numbers)):
        value = numbers[index]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element %d is not a number: %r" % (index, value))
        cleaned.append(float(value))
    return cleaned


def sort_ascending(values):
    """Selection sort, so the trimming order is explicit and stable."""
    ordered = list(values)
    for index in range(len(ordered)):
        smallest = index
        for column in range(index + 1, len(ordered)):
            if ordered[column] < ordered[smallest]:
                smallest = column
        ordered[index], ordered[smallest] = ordered[smallest], ordered[index]
    return ordered


def trim_extremes(values, num_to_exclude):
    """Drop the num_to_exclude smallest and largest values."""
    ordered = sort_ascending(values)
    kept = []
    for key in range(num_to_exclude, len(ordered) - num_to_exclude):
        kept.append(ordered[key])
    return kept


def calculate_average_no_outliers(numbers, num_to_exclude):
    values = validate_numbers(numbers)
    if num_to_exclude < 0:
        raise ValueError("num_to_exclude must not be negative")
    if 2 * num_to_exclude >= len(values):
        return 0.0
    kept = trim_extremes(values, num_to_exclude)
    total = 0.0
    for index in range(len(kept)):
        total += kept[index]
    return total / len(kept)


def format_report(numbers, num_to_exclude):
    values = validate_numbers(numbers)
    average = calculate_average_no_outliers(values, num_to_exclude)
    if 2 * num_to_exclude >= len(values):
        detail = "nothing left after trimming"
    else:
        kept = trim_extremes(values, num_to_exclude)
        pieces = []
        for index in range(len(kept)):
            pieces.append("%g" % kept[index])
        detail = "kept " + ", ".join(pieces)
    return "trim %d: %s -> %.4f" % (num_to_exclude, detail, average)


def main():
    datasets = [
        ([1, 2, 3, 100], 1),
        ([10, 20, 30, 40, 50], 0),
        ([5, 5, 5, 5], 2),
        ([-3.5, 0, 2.25, 7, 12, 40], 1),
