def calculate_hamming_distance(s1, s2):
    """Number of positions at which s1 and s2 differ."""
    if len(s1) != len(s2):
        raise ValueError("strings must have equal length")
    distance = 0
    for i in range(len(s1)):
        if s1[i] != s2[i]:
            distance += 1
    return distance


def mismatch_positions(s1, s2):
    """Indices where the two strings differ."""
    if len(s1) != len(s2):
        raise ValueError("strings must have equal length")
    positions = []
    for j in range(len(s1)):
        if s1[j] != s2[j]:
            positions.append(j)
    return positions


def difference_marker(s1, s2, mark="^"):
    """A caret line under each differing column."""
    marks = [" "] * len(s1)
    for k in mismatch_positions(s1, s2):
        marks[k] = mark
    return "".join(marks)


def distance_matrix(words):
    """Square matrix of pairwise Hamming distances (equal-length words)."""
    matrix = []
    for i in range(len(words)):
        row = []
        for j in range(len(words)):
            row.append(calculate_hamming_distance(words[i], words[j]))
        matrix.append(row)
    return matrix


def format_matrix(words, matrix):
    """Render the matrix with row labels as lines of text."""
    width = max(len(word) for word in words)
    lines = []
    for i in range(len(words)):
        cells = []
        for j in range(len(words)):
            cells.append("%2d" % matrix[i][j])
        lines.append("%-*s  %s" % (width, words[i], " ".join(cells)))
    return lines


def closest_pair(words, matrix):
    """The pair of words with the smallest Hamming distance."""
    best = None
    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            if best is None or matrix[i][j] < best[2]:
                best = (words[i], words[j], matrix[i][j])
    return best


def main():
    pairs = [("karolin", "kathrin"), ("python", "python"), ("karolin", "kerstin")]
    for first, second in pairs:
        print("%s vs %s -> %d" % (first, second,
                                  calculate_hamming_distance(first, second)))
        print("  " + first)
        print("  " + second)
        print("  " + difference_marker(first, second))

    words = ["karolin", "kathrin", "kerstin", "kerolin"]
    matrix = distance_matrix(words)
    print("\nPairwise distances:")
    for line in format_matrix(words, matrix):
        print("  " + line)
    first, second, distance = closest_pair(words, matrix)
    print("Closest: %s / %s (%d)" % (first, second, distance))


if __name__ == "__main__":
    main()

