def _check_sequence(name, value):
    """Raise a TypeError unless value is a list or tuple."""
    if not isinstance(value, (list, tuple)):
        raise TypeError("%s must be a list or tuple, got %s" % (name, type(value).__name__))


def _dedupe(values):
    """Return the values in order, keeping only the first occurrence of each."""
    unique = []
    for i in range(len(values)):
        if values[i] not in unique:
            unique.append(values[i])
    return unique


def find_common_elements(list1, list2):
    """Return the elements appearing in both lists, without duplicates."""
    _check_sequence("list1", list1)
    _check_sequence("list2", list2)
    common = []
    for i in range(len(list1)):
        item = list1[i]
        if item in common:
            continue
        for j in range(len(list2)):
            if item == list2[j]:
                common.append(item)
                break
    return common


def common_to_all(lists):
    """Return the elements shared by every list in lists, without duplicates."""
    if not lists:
        return []
    result = _dedupe(lists[0])
    for i in range(1, len(lists)):
        result = find_common_elements(result, lists[i])
        if not result:
            break
    return result


def format_elements(values):
    """Render a collection of values as a set-like string."""
    parts = []
    for i in range(len(values)):
        parts.append(repr(values[i]))
    return "{" + ", ".join(parts) + "}"


def format_report(groups):
    """Build numbered report lines for a sequence of lists-of-lists."""
    lines = []
    for i in range(len(groups)):
        group = groups[i]
        shared = common_to_all(group)
        rendered = []
        for j in range(len(group)):
            rendered.append(format_elements(list(group[j])))
        lines.append("%d. %s -> %s (%d shared)"
                     % (i + 1, " & ".join(rendered), format_elements(shared), len(shared)))
    return lines


def main():
    groups = [
        [[1, 2, 3, 4], [3, 4, 5, 6]],
        [[1, 2], [3, 4]],
        [["a", "b", "b", "c"], ["c", "b", "z"]],
        [[1, 2, 3, 4], [2, 3, 4, 5], [3, 4, 9]],
    ]
    lines = format_report(groups)
    for i in range(len(lines)):
        print(lines[i])

    pair = groups[0]
    print("pairwise check:", find_common_elements(pair[0], pair[1]))


if __name__ == "__main__":
    main()

