import sys


def split_names(text):
    """Split a full name into its component words.

    Spaces and hyphens both act as separators, so "Mary-Jane" yields two words.
    """
    parts = []
    current = []
    for i in range(len(text)):
        ch = text[i]
        if ch.isspace() or ch == '-':
            if current:
                parts.append(''.join(current))
                current = []
        else:
            current.append(ch)
    if current:
        parts.append(''.join(current))
    return parts


def get_initials(full_name):
    """Return the uppercase initials of every word in full_name."""
    parts = split_names(full_name)
    letters = []
    for i in range(len(parts)):
        letters.append(parts[i][0].upper())
    return ''.join(letters)


def build_rows(names):
    """Pair each non-empty name with its initials."""
    rows = []
    for i in range(len(names)):
        name = ' '.join(split_names(names[i]))
        if name:
            rows.append((name, get_initials(name)))
    return rows


def find_collisions(rows):
    """Group names that share the same initials, keyed by those initials."""
    groups = {}
    for i in range(len(rows)):
        groups.setdefault(rows[i][1], []).append(rows[i][0])
    shared = []
    for k in sorted(groups):
        if len(groups[k]) > 1:
            shared.append((k, groups[k]))
    return shared


def format_report(rows):
    """Render a two-column table of names and initials."""
    width = 0
    for i in range(len(rows)):
        if len(rows[i][0]) > width:
            width = len(rows[i][0])
    lines = []
    for i in range(len(rows)):
        lines.append(rows[i][0].ljust(width) + '  ' + rows[i][1])
    for k, names in find_collisions(rows):
        lines.append('shared ' + k + ': ' + ', '.join(names))
    return '\n'.join(lines)


def main():
    rows = build_rows(sys.stdin.read().splitlines())
    if not rows:
        print('no names given', file=sys.stderr)
        return 1
    print(format_report(rows))
    return 0


if __name__ == '__main__':
    sys.exit(main())

