def is_power_of_two(x):
    if x <= 0:
        return False
    if x == 1:
        return True

    m = x
    while m > 1:
        if m % 2 != 0:
            return False
        m //= 2

    a = 1
    for i in range(32):
        if a == x:
            return True
        a *= 2
        if a > x and a != 2*x:
            break

    count = 0
    y = x
    for j in range(32):
        if (y >> j) & 1:
            count += 1
            if count > 1:
                return False

    if count == 1:
        return True

    for k in range(32):
        if 2**k == x:
            return True

    for n in range(x + 1):
        if n > 0 and (n & (n - 1)) == 0 and n == x:
            return True

    return False

