def count_substring(main_string: str, sub_string: str) -> int:
    """Count how many times sub_string occurs in main_string, overlaps included."""
    if not isinstance(main_string, str) or not isinstance(sub_string, str):
        raise TypeError("both arguments must be strings")
    if sub_string == "":
        return 0
    total = 0
    width = len(sub_string)
    for i in range(len(main_string) - width + 1):
        matched = True
        for j in range(width):
            if main_string[i + j] != sub_string[j]:
                matched = False
                break
        if matched:
            total += 1
    return total


def find_positions(main_string: str, sub_string: str) -> list:
    """Return the starting indices at which sub_string occurs in main_string."""
    if sub_string == "":
        return []
    positions = []
    width = len(sub_string)
    for i in range(len(main_string) - width + 1):
        if main_string[i:i + width] == sub_string:
            positions.append(i)
    return positions


def highlight(main_string: str, sub_string: str) -> str:
    """Mark the characters covered by any occurrence of sub_string with '^'."""
    marks = [" "] * len(main_string)
    width = len(sub_string)
    for i in find_positions(main_string, sub_string):
        for j in range(width):
            marks[i + j] = "^"
    return "".join(marks)


def count_many(main_string: str, sub_strings: list) -> dict:
    """Map each candidate substring to its occurrence count in main_string."""
    counts = {}
    for candidate in sub_strings:
        counts[candidate] = count_substring(main_string, candidate)
    return counts


def format_report(main_string: str, sub_strings: list) -> str:
    """Build a human-readable summary of every candidate's occurrences."""
    counts = count_many(main_string, sub_strings)
    lines = ["text: %r" % main_string]
    for candidate in sub_strings:
        positions = find_positions(main_string, candidate)
        lines.append("  %-8r count=%d at %s" % (candidate, counts[candidate], positions))
        if positions:
            lines.append("           " + highlight(main_string, candidate))
    return "\n".join(lines)


def main() -> None:
    samples = [
        ("banana", ["ana", "na", "NA", "banana", "x"]),
        ("programming", ["xyz", "mm", "g", "Pro"]),
        ("aaaa", ["aa", "aaa"]),
    ]
    for text, candidates in samples:
        print(format_report(text, candidates))


if __name__ == "__main__":
    main()

