def parse_csv_string(csv_data: str) -> list[list[str]]:
    """Parse a multi-line CSV string into a list of rows of string fields."""
    rows = []
    lines = csv_data.split("\n")
    for i in range(len(lines)):
        line = lines[i].rstrip("\r")
        if line == "" and i == len(lines) - 1:
            continue
        parts = line.split(",")
        row = []
        for j in range(len(parts)):
            row.append(parts[j].strip())
        rows.append(row)
