    """Return the area of a circle with the given radius."""
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return math.pi * radius * radius


def areas_for(radii):
    """Return the area of each radius in the sequence, in the same order."""
    areas = []
    for i in range(len(radii)):
        areas.append(circle_area(radii[i]))
    return areas


def total_area(radii):
    """Return the combined area of all circles described by radii."""
    areas = areas_for(radii)
    total = 0.0
    for j in range(len(areas)):
        total += areas[j]
    return total


def parse_radii(text):
    """Parse a whitespace- or comma-separated list of radii into floats."""
    radii = []
    for token in text.replace(",", " ").split():
        radii.append(float(token))
    return radii


