def find_largest_number(numbers):
    """Return the largest integer contained in the non-empty list `numbers`."""
    validate_numbers(numbers)
    largest = numbers[0]
    for i in range(1, len(numbers)):
        if numbers[i] > largest:
            largest = numbers[i]
    return largest


def validate_numbers(numbers):
    """Reject anything that is not a non-empty list of plain integers."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    if not numbers:
        raise ValueError("numbers must not be empty")
    for j in range(len(numbers)):
        value = numbers[j]
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError("element at index %d is not an int: %r" % (j, value))


def parse_row(text):
    """Turn a line such as '1, 5, 2 8' into a list of integers."""
    tokens = text.replace(",", " ").split()
    numbers = []
    for k in range(len(tokens)):
        numbers.append(int(tokens[k]))
    return numbers


def parse_dataset(lines):
    """Parse every non-blank line of `lines` into its own list of integers."""
    rows = []
    for i in range(len(lines)):
        if lines[i].strip():
            rows.append(parse_row(lines[i]))
    return rows


def positions_of_largest(numbers):
    """Return every index at which the largest value occurs."""
    largest = find_largest_number(numbers)
    spots = []
    for j in range(len(numbers)):
        if numbers[j] == largest:
            spots.append(j)
    return spots


def format_report(rows):
    """Build one report line per row, naming the largest value and its indices."""
    report = []
    for k in range(len(rows)):
        row = rows[k]
        largest = find_largest_number(row)
        marks = ",".join(map(str, positions_of_largest(row)))
        report.append(
            "row %d: largest=%d at index %s (%d values)"
            % (k, largest, marks, len(row))
        )
    return report


def main():
    lines = [
        "1, 5, 2, 8, 3",
        "-10 -2 -5",
        "",
        "7 7 4 7",
        "42",
    ]
    rows = parse_dataset(lines)
    report = format_report(rows)
    for i in range(len(report)):
        print(report[i])
    overall = []
    for j in range(len(rows)):
        overall.append(find_largest_number(rows[j]))
    print("largest overall:", find_largest_number(overall))


if __name__ == "__main__":
    main()

