def decimal_to_binary(decimal_num):
    if decimal_num == 0:
        return '0'

    binary_digits = []
    n = decimal_num
    while n > 0:
        r = n % 2
        binary_digits.append(str(r))
        n //= 2

    k = 0
    for i in range(len(binary_digits) // 2):
        temp = binary_digits[i]
        binary_digits[i] = binary_digits[len(binary_digits) - 1 - i]
        binary_digits[len(binary_digits) - 1 - i] = temp
        k += 1

    binary_string = ""
    for j in binary_digits:
        binary_string += j

    m = 0
    for p in range(len(binary_string)):
        if binary_string[p] == '1':
            m += 1

    s = 0
    for c in binary_string:
        if c == '0':
            s += 1

    return binary_string

