def _validate(nums, k):
    if not isinstance(nums, list):
        raise TypeError("nums must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be non-negative")


def _reverse(nums, lo, hi):
    for i in range((hi - lo + 1) // 2):
        nums[lo + i], nums[hi - i] = nums[hi - i], nums[lo + i]


def rotate_list(nums, k):
    _validate(nums, k)
    size = len(nums)
    if size == 0:
        return nums
    k %= size
    if k == 0:
        return nums
    _reverse(nums, 0, size - 1)
    _reverse(nums, 0, k - 1)
    _reverse(nums, k, size - 1)
    return nums


def all_rotations(nums):
    rotations = []
    for i in range(len(nums)):
        rotations.append(rotate_list(list(nums), i))
    return rotations


def format_table(nums):
    rotations = all_rotations(nums)
    if not rotations:
        return "(empty list has no rotations)"
    cells = []
    for i in range(len(rotations)):
        row = ["k=%d" % i]
        for j in range(len(rotations[i])):
            row.append(str(rotations[i][j]))
        cells.append(row)
    widths = [0] * len(cells[0])
    for row in cells:
        for j in range(len(row)):
            widths[j] = max(widths[j], len(row[j]))
    lines = []
    for row in cells:
        parts = []
        for j in range(len(row)):
            parts.append(row[j].rjust(widths[j]))
        lines.append("  ".join(parts))
    return "\n".join(lines)


def main():
    cases = [([1, 2, 3, 4, 5, 6, 7], 3), ([-1, -100, 3, 99], 2), ([], 5), ([7], 4)]
    for i in range(len(cases)):
        nums, steps = cases[i]
        original = list(nums)
        rotated = rotate_list(nums, steps)
        print("case %d: %r rotated by %d -> %r" % (i + 1, original, steps, rotated))
    print()
    print("all rotations of [1, 2, 3, 4, 5]:")
    print(format_table([1, 2, 3, 4, 5]))


if __name__ == "__main__":
    main()

