def validate_tasks(tasks: list) -> None:
    """Raise a descriptive error if the task list is malformed."""
    if not isinstance(tasks, list):
        raise TypeError("tasks must be a list of dictionaries")
    for i, task in enumerate(tasks):
        if not isinstance(task, dict):
            raise TypeError("task at index %d is not a dictionary" % i)
        for k in ("name", "priority"):
            if k not in task:
                raise KeyError("task at index %d is missing '%s'" % (i, k))
        if not isinstance(task["priority"], int) or isinstance(task["priority"], bool):
            raise TypeError("priority of task at index %d must be an int" % i)


def sort_tasks_by_priority(tasks: list) -> list:
    """Return task names ordered by ascending priority (lower = more urgent)."""
    validate_tasks(tasks)
    ordered = list(tasks)
    for i in range(1, len(ordered)):
        current = ordered[i]
        j = i - 1
        while j >= 0 and ordered[j]["priority"] > current["priority"]:
            ordered[j + 1] = ordered[j]
            j -= 1
        ordered[j + 1] = current
    return [task["name"] for task in ordered]


def group_by_priority(tasks: list) -> dict:
    """Map each priority value to the names carrying it, in input order."""
    validate_tasks(tasks)
    groups = {}
    for task in tasks:
        groups.setdefault(task["priority"], []).append(task["name"])
    return groups


def format_report(tasks: list) -> str:
    """Build a human readable, priority ordered listing of the tasks."""
    groups = group_by_priority(tasks)
    lines = []
    for k in sorted(groups):
        label = "priority %d" % k
        for j, name in enumerate(groups[k]):
            prefix = label if j == 0 else " " * len(label)
            lines.append("%s | %s" % (prefix, name))
    if not lines:
        return "no tasks"
    return "\n".join(lines)


