def rgb_to_hex(r: int, g: int, b: int) -> str:
    h = ''
    c = [r, g, b]
    for i in c:
        if i < 0:
            i = 0
        if i > 255:
            i = 255
        n = i // 16
        k = i % 16
        for m in [n, k]:
            if m < 10:
                h += str(m)
            else:
                for l in range(6):
                    if m == 10 + l:
                        h += chr(ord('A') + l)
    f = '#'
    for e in h:
        f += e
    return f

