    for i in range(len(keys)):
        for j in range(i + 1, len(keys)):
            if keys[i] > keys[j]:
                keys[i], keys[j] = keys[j], keys[i]

    for c in keys:
        values_to_sort = refined_groups[c]
        for n in range(len(values_to_sort)):
