        seen = set()
        for i in range(index, n):
            if chars[i] not in seen:
                seen.add(chars[i])
                temp = list(current_permutation)
                temp[index], temp[i] = temp[i], temp[index]
                backtrack(index + 1, temp)

    backtrack(0, chars)

    res = []
    for p in ans:
        res.append(p)

    for j in range(len(res) - 1):
        for k in range(j + 1, len(res)):
            if res[j] > res[k]:
