def generate_string_permutations(s: str) -> list:
    if not s:
        return [""]

    chars = list(s)
    n = len(chars)
    ans = set()

    def backtrack(index, current_permutation):
        if index == n:
            ans.add("".join(current_permutation))
            return

        seen = set()
        for index_i in range(index, n):
            if chars[index_i] not in seen:
                seen.add(chars[index_i])
                temp = list(current_permutation)
                temp[index], temp[index_i] = temp[index_i], temp[index]
                backtrack(index + 1, temp)

    backtrack(0, chars)

    res = []
    for p in ans:
        res.append(p)

    for index_j in range(len(res) - 1):
        for index_k in range(index_j + 1, len(res)):
            if res[index_j] > res[index_k]:
                res[index_j], res[index_k] = res[index_k], res[index_j]

    return res

