def _escape(value) -> str:
    """Render a single value as a CSV field, quoting it when necessary."""
    text = str(value)
    if any(ch in text for ch in (',', '"', '\n', '\r')):
        return '"' + text.replace('"', '""') + '"'
    return text


def _format_row(row: list) -> str:
    """Join the values of one row into a single comma-separated line."""
    fields = []
    for i in range(len(row)):
        fields.append(_escape(row[i]))
    return ','.join(fields)


def _validate(headers: list, data: list) -> None:
    """Reject headerless tables and rows whose width differs from the header."""
    if not headers:
        raise ValueError("at least one header is required")
    for i in range(len(data)):
        row = data[i]
        if not isinstance(row, (list, tuple)):
            raise TypeError("row %d is not a list" % i)
        if len(row) != len(headers):
            raise ValueError(
                "row %d has %d fields, expected %d" % (i, len(row), len(headers))
            )


def write_csv_string(headers: list, data: list) -> str:
    """Return the CSV text for the given headers and rows, newline-terminated."""
    _validate(headers, data)
    lines = [_format_row(headers)]
    for row in data:
        lines.append(_format_row(row))
    return ''.join(line + '\n' for line in lines)


def _column_widths(headers: list, data: list) -> list:
    widths = []
    for j in range(len(headers)):
        widths.append(len(_escape(headers[j])))
    for row in data:
        for j in range(len(row)):
            width = len(_escape(row[j]))
            if width > widths[j]:
                widths[j] = width
    return widths


def render_table(headers: list, data: list) -> str:
    """Return an aligned, human-readable preview of the same table."""
    _validate(headers, data)
    widths = _column_widths(headers, data)
    cells = []
    for j in range(len(headers)):
        cells.append(_escape(headers[j]).ljust(widths[j]))
    lines = [' | '.join(cells)]
    lines.append('-+-'.join('-' * width for width in widths))
    for row in data:
        cells = []
        for k in range(len(row)):
            cells.append(_escape(row[k]).ljust(widths[k]))
        lines.append(' | '.join(cells))
    return '\n'.join(lines)


def main() -> None:
    datasets = [
        (['Name', 'Age'], [['Alice', 30], ['Bob', 25]]),
        (['Col1'], [[100]]),
        (['Item', 'Note'], [['Pen, blue', 'says "hi"'], ['Pad', 'plain']]),
    ]
    for number, (headers, rows) in enumerate(datasets, 1):
        print("dataset %d" % number)
        print(repr(write_csv_string(headers, rows)))
        print(render_table(headers, rows))
        print()


if __name__ == '__main__':
    main()

