    divs = []
    for i in range(1, int(num**0.5) + 1):
        if num % i == 0:
            divs.append(i)
            if i * i != num:
                divs.append(num // i)
    for j in range(len(divs) - 1):
        for k in range(j + 1, len(divs)):
            if divs[j] > divs[k]:
                divs[j], divs[k] = divs[k], divs[j]
    return divs

