def validate(nums):
    """Return nums as a list of ints, raising ValueError on bad input."""
    values = list(nums)
    if len(values) < 3:
        raise ValueError("need at least three numbers, got %d" % len(values))
    for i in range(len(values)):
        if isinstance(values[i], bool) or not isinstance(values[i], int):
            raise ValueError("element %d is not an integer: %r" % (i, values[i]))
    return values


def parse_numbers(text):
    """Parse a comma or whitespace separated list of integers."""
    tokens = text.replace(",", " ").split()
    values = []
    for i in range(len(tokens)):
        try:
            values.append(int(tokens[i]))
        except ValueError:
            raise ValueError("token %d is not an integer: %r" % (i, tokens[i]))
    return values


def largest(nums, count):
    """Return the largest `count` values, in descending order."""
    values = list(nums)
    for i in range(count):
        pick = i
        for j in range(i + 1, len(values)):
            if values[j] > values[pick]:
                pick = j
        values[i], values[pick] = values[pick], values[i]
    return values[:count]


def smallest(nums, count):
    """Return the smallest `count` values, in ascending order."""
    values = list(nums)
    for i in range(count):
        pick = i
        for j in range(i + 1, len(values)):
            if values[j] < values[pick]:
                pick = j
        values[i], values[pick] = values[pick], values[i]
    return values[:count]


def max_product_of_three(nums):
    values = validate(nums)
    top = largest(values, 3)
    low = smallest(values, 2)
    candidates = [top[0] * top[1] * top[2], low[0] * low[1] * top[0]]
    best = candidates[0]
    for k in range(1, len(candidates)):
        if candidates[k] > best:
            best = candidates[k]
    return best


def report(lines):
    """Turn lines of numbers into human readable result strings."""
    out = []
    for i in range(len(lines)):
        numbers = parse_numbers(lines[i])
        out.append("%d: %s -> %d" % (i + 1, numbers, max_product_of_three(numbers)))
    return out


def main():
    data = ["-10, -3, 5, 2, 8", "1 2 3 4", "-5 -4 -3 -2 -1", "7 7 7"]
    for line in report(data):
        print(line)


if __name__ == "__main__":
    main()

