def is_valid_ipv4_segment(segment):
    """Return True if `segment` is a valid IPv4 segment ("0" to "255")."""
    if not segment or len(segment) > 3:
        return False
    for i in range(len(segment)):
        if segment[i] not in '0123456789':
            return False
    if segment[0] == '0' and len(segment) > 1:
        return False
    value = 0
    for i in range(len(segment)):
        value = value * 10 + (ord(segment[i]) - ord('0'))
    return value <= 255


def is_valid_ipv4_address(address):
    """Return True if `address` is four valid dot-separated segments."""
    parts = address.split('.')
    if len(parts) != 4:
        return False
    for i in range(4):
        if not is_valid_ipv4_segment(parts[i]):
            return False
    return True


def restore_ip_addresses(digits):
    """Return every valid IPv4 address obtainable by inserting dots in `digits`."""
    results = []
    size = len(digits)
    for i in range(1, 4):
        for j in range(i + 1, i + 4):
            for k in range(j + 1, j + 4):
                if k >= size or size - k > 3:
                    continue
                candidate = '.'.join([digits[:i], digits[i:j],
                                      digits[j:k], digits[k:]])
                if is_valid_ipv4_address(candidate):
                    results.append(candidate)
    return results


def segment_report(segments):
    """Build aligned "segment -> verdict" lines for a list of segment strings."""
    width = 0
    for i in range(len(segments)):
        shown = repr(segments[i])
        if len(shown) > width:
            width = len(shown)
    lines = []
    for i in range(len(segments)):
        verdict = 'valid' if is_valid_ipv4_segment(segments[i]) else 'invalid'
        lines.append('%-*s -> %s' % (width, repr(segments[i]), verdict))
    return lines


def main():
    samples = ['192', '256', '0', '00', '255', '', '7a', '1000', ' 12']
    for line in segment_report(samples):
        print(line)

    addresses = ['192.168.0.1', '192.168.01.1', '1.2.3', '255.255.255.255']
    for i in range(len(addresses)):
        state = 'valid' if is_valid_ipv4_address(addresses[i]) else 'invalid'
        print('address %d: %s is %s' % (i + 1, addresses[i], state))

    for digits in ['25525511135', '0000', '101023']:
        candidates = restore_ip_addresses(digits)
        print('%s yields %d address(es):' % (digits, len(candidates)))
        for j in range(len(candidates)):
            print('  %d. %s' % (j + 1, candidates[j]))


if __name__ == '__main__':
    main()

