HEX_DIGITS = "0123456789ABCDEF"


def validate_binary(binary_str):
    """Return the string stripped of separators, or raise ValueError."""
    cleaned = []
    for i, ch in enumerate(binary_str):
        if ch in "_ ":
            continue
        if ch not in "01":
            raise ValueError("invalid binary digit %r at position %d" % (ch, i))
        cleaned.append(ch)
    if not cleaned:
        raise ValueError("empty binary string")
    return "".join(cleaned)


def pad_to_nibbles(bits):
    """Left-pad with zeros so the length is a multiple of four."""
    remainder = len(bits) % 4
    if remainder == 0:
        return bits
    return "0" * (4 - remainder) + bits


def nibble_to_hex(nibble):
    """Convert exactly four bits to a single hexadecimal character."""
    value = 0
    for j in range(4):
        value = value * 2 + (1 if nibble[j] == "1" else 0)
    return HEX_DIGITS[value]


def binary_to_hex(binary_str):
    """Convert a binary string to its hexadecimal representation."""
    bits = pad_to_nibbles(validate_binary(binary_str))
    digits = []
    for k in range(0, len(bits), 4):
        digits.append(nibble_to_hex(bits[k:k + 4]))
    while len(digits) > 1 and digits[0] == "0":
        digits.pop(0)
    return "".join(digits)


def group_bits(binary_str, size=4):
    """Format a binary string as space-separated groups for display."""
    bits = pad_to_nibbles(validate_binary(binary_str))
    groups = []
    for i in range(0, len(bits), size):
        groups.append(bits[i:i + size])
    return " ".join(groups)


def conversion_report(samples):
    """Build aligned report lines for a sequence of binary strings."""
    grouped = []
    for i in range(len(samples)):
        grouped.append(group_bits(samples[i]))
    width = max(len(text) for text in grouped)
    lines = []
    for j, sample in enumerate(samples, start=1):
        lines.append("%2d. %-*s -> 0x%s" % (j, width, grouped[j - 1], binary_to_hex(sample)))
    return lines


def main():
    samples = ["1011", "11110000", "1", "1111_1111_0000", "0000 0001", "110101101"]
    for line in conversion_report(samples):
        print(line)
    try:
        binary_to_hex("10201")
    except ValueError as exc:
        print("rejected: %s" % exc)


if __name__ == "__main__":
    main()

