def _validate_dimension(name, value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("%s must be a number, got %r" % (name, value))
    if value < 0:
        raise ValueError("%s must not be negative, got %r" % (name, value))
    return float(value)


def calculate_triangle_area(base, height):
    b = _validate_dimension("base", base)
    h = _validate_dimension("height", height)
    return 0.5 * b * h


def parse_pairs(lines):
    pairs = []
    for i, line in enumerate(lines, start=1):
        text = line.strip()
        if not text:
            continue
        fields = text.replace(",", " ").split()
        if len(fields) != 2:
            raise ValueError("line %d: expected 'base height', got %r" % (i, text))
        try:
            pairs.append((float(fields[0]), float(fields[1])))
        except ValueError:
            raise ValueError("line %d: non-numeric dimension in %r" % (i, text))
    return pairs


def total_area(pairs):
    running = 0.0
    for base, height in pairs:
        running += calculate_triangle_area(base, height)
    return running


def format_report(pairs):
    lines = []
    for k, (base, height) in enumerate(pairs, start=1):
        lines.append("triangle %d: base=%.1f height=%.1f area=%.2f"
                     % (k, base, height, calculate_triangle_area(base, height)))
    lines.append("total area: %.2f" % total_area(pairs))
