def _validate_dimension(name, value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("%s must be a number, got %r" % (name, value))
    if value < 0:
        raise ValueError("%s must not be negative, got %r" % (name, value))
    return float(value)


def calculate_triangle_area(base, height):
    b = _validate_dimension("base", base)
    h = _validate_dimension("height", height)
    return 0.5 * b * h


def parse_pairs(lines):
    pairs = []
    for index, line in enumerate(lines, start=1):
        text = line.strip()
        if not text:
            continue
        fields = text.replace(",", " ").split()
        if len(fields) != 2:
            raise ValueError("line %d: expected 'base height', got %r" % (index, text))
        try:
            pairs.append((float(fields[0]), float(fields[1])))
        except ValueError:
            raise ValueError("line %d: non-numeric dimension in %r" % (index, text))
    return pairs


