        raise ValueError("values must not be empty")
    for index in range(len(values)):
        if not isinstance(values[index], (int, float)) or isinstance(values[index], bool):
            raise TypeError("value at index %d is not numeric" % index)
        if not isinstance(weights[index], (int, float)) or isinstance(weights[index], bool):
            raise TypeError("weight at index %d is not numeric" % index)
        if weights[index] < 0:
            raise ValueError("weight at index %d is negative" % index)


def calculate_weighted_average(values, weights):
    validate_inputs(values, weights)
    total = 0.0
    weight_sum = 0.0
    for index in range(len(values)):
        total += values[index] * weights[index]
        weight_sum += weights[index]
    if weight_sum == 0:
        raise ValueError("sum of weights must be greater than zero")
    return total / weight_sum


def normalize_weights(weights):
    weight_sum = 0.0
    for index in range(len(weights)):
        weight_sum += weights[index]
    if weight_sum == 0:
        raise ValueError("sum of weights must be greater than zero")
    normalized = []
    for column in range(len(weights)):
        normalized.append(weights[column] / weight_sum)
    return normalized


def weighted_variance(values, weights):
    mean = calculate_weighted_average(values, weights)
    shares = normalize_weights(weights)
    variance = 0.0
    for key in range(len(values)):
        variance += shares[key] * (values[key] - mean) ** 2
    return variance


def format_report(label, values, weights):
    shares = normalize_weights(weights)
    lines = ["%s (%d entries)" % (label, len(values))]
    for index in range(len(values)):
        lines.append("  value=%8.3f  weight=%6.3f  share=%6.2f%%"
                     % (values[index], weights[index], shares[index] * 100.0))
    lines.append("  weighted average = %.4f" % calculate_weighted_average(values, weights))
    lines.append("  weighted variance = %.4f" % weighted_variance(values, weights))
    return "\n".join(lines)


def main():
    datasets = [
        ("Sample A", [10, 20, 30], [0.5, 0.3, 0.2]),
        ("Sample B", [5, 10], [1, 1]),
        ("Exam scores", [88, 92.5, 74, 100], [2, 3, 1, 4]),
    ]
    for index in range(len(datasets)):
        print(format_report(datasets[index][0], datasets[index][1], datasets[index][2]))
        print()

    means = []
    counts = []
    for column in range(len(datasets)):
        means.append(calculate_weighted_average(datasets[column][1], datasets[column][2]))
        counts.append(len(datasets[column][1]))
    print("Combined average of dataset means:")
    print("  %.4f" % calculate_weighted_average(means, counts))


if __name__ == "__main__":
    main()

