def generate_fibonacci(n: int) -> list[int]:
    """Return the first ``n`` Fibonacci numbers, starting with 0 and 1."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")
    seq = [0, 1][:n]
    for i in range(2, n):
        seq.append(seq[i - 1] + seq[i - 2])
    return seq


def partial_sums(seq: list[int]) -> list[int]:
    """Running totals, where each entry sums the terms up to that position."""
    sums = []
    total = 0
    for j in range(len(seq)):
        total += seq[j]
        sums.append(total)
    return sums


def consecutive_ratios(seq: list[int]) -> list[float | None]:
    """Ratio of each term to its predecessor; None where it is undefined."""
    ratios = []
    for i in range(len(seq)):
        if i >= 2:
            ratios.append(seq[i] / seq[i - 1])
        else:
            ratios.append(None)
    return ratios


def digit_sum(value: int) -> int:
    """Sum of the decimal digits of a non-negative integer."""
    total = 0
    for k in str(value):
        total += int(k)
    return total


def format_table(seq: list[int]) -> str:
    """Render a sequence as an aligned text table with derived columns."""
    sums = partial_sums(seq)
    ratios = consecutive_ratios(seq)
    term_width = len("term")
    for i in range(len(seq)):
        term_width = max(term_width, len(str(seq[i])))
    sum_width = len("partial")
    for j in range(len(sums)):
        sum_width = max(sum_width, len(str(sums[j])))
    lines = [
        f"{'idx':>3}  {'term':>{term_width}}  {'digits':>6}  "
        f"{'partial':>{sum_width}}  ratio"
    ]
    for k in range(len(seq)):
        ratio = ratios[k]
        shown = "-" if ratio is None else f"{ratio:.6f}"
        lines.append(
            f"{k:>3}  {seq[k]:>{term_width}}  {digit_sum(seq[k]):>6}  "
            f"{sums[k]:>{sum_width}}  {shown}"
        )
    return "\n".join(lines)


def main() -> None:
    for k in (1, 5, 12):
        print(f"generate_fibonacci({k}) == {generate_fibonacci(k)}")
    print()
    print(format_table(generate_fibonacci(15)))


if __name__ == "__main__":
    main()

