def _validate(label: str, value: str) -> None:
    if not isinstance(value, str):
        raise TypeError(label + " must be a string")
    for i in range(len(value)):
        if not ("a" <= value[i] <= "z"):
            raise ValueError(label + " must contain only lowercase letters, found " + repr(value[i]))


def letter_counts(s: str) -> list:
    counts = [0] * 26
    for i in range(len(s)):
        counts[ord(s[i]) - 97] += 1
    return counts


def _same_counts(a: list, b: list) -> bool:
    for k in range(26):
        if a[k] != b[k]:
            return False
    return True


def find_anagram_positions(text: str, pattern: str) -> list:
    _validate("text", text)
    _validate("pattern", pattern)
    n = len(pattern)
    if n == 0 or len(text) < n:
        return []
    needed = letter_counts(pattern)
    window = letter_counts(text[:n])
    positions = []
    if _same_counts(window, needed):
        positions.append(0)
    for i in range(n, len(text)):
        window[ord(text[i]) - 97] += 1
        window[ord(text[i - n]) - 97] -= 1
        if _same_counts(window, needed):
            positions.append(i - n + 1)
    return positions


def count_substring_anagrams(text: str, pattern: str) -> int:
    return len(find_anagram_positions(text, pattern))


def highlight(text: str, positions: list) -> str:
    marks = [" "] * len(text)
    for k in positions:
        marks[k] = "^"
    return "".join(marks)


def report(text: str, pattern: str) -> str:
    positions = find_anagram_positions(text, pattern)
    lines = ["text=%r pattern=%r -> %d anagram substring(s)" % (text, pattern, len(positions))]
    lines.append("  " + text)
    lines.append("  " + highlight(text, positions))
    for j in range(len(positions)):
        start = positions[j]
        lines.append("  [%d] index %d: %s" % (j, start, text[start:start + len(pattern)]))
    return "\n".join(lines)


def main() -> None:
    cases = [
        ("cbaebabacd", "abc"),
        ("abab", "ab"),
        ("aaaaa", "aa"),
        ("zzz", "abc"),
    ]
    for i in range(len(cases)):
        text, pattern = cases[i]
        print(report(text, pattern))
        print()


