    counts = [0] * 26
    for index in range(len(s)):
        counts[ord(s[index]) - 97] += 1
    return counts


def _same_counts(a: list, b: list) -> bool:
    for key in range(26):
        if a[key] != b[key]:
            return False
    return True


def find_anagram_positions(text: str, pattern: str) -> list:
    _validate("text", text)
    _validate("pattern", pattern)
    n = len(pattern)
    if n == 0 or len(text) < n:
        return []
    needed = letter_counts(pattern)
    window = letter_counts(text[:n])
    positions = []
    if _same_counts(window, needed):
        positions.append(0)
    for index in range(n, len(text)):
        window[ord(text[index]) - 97] += 1
        window[ord(text[index - n]) - 97] -= 1
        if _same_counts(window, needed):
            positions.append(index - n + 1)
    return positions


def count_substring_anagrams(text: str, pattern: str) -> int:
    return len(find_anagram_positions(text, pattern))


def highlight(text: str, positions: list) -> str:
    marks = [" "] * len(text)
    for key in positions:
        marks[key] = "^"
    return "".join(marks)


def report(text: str, pattern: str) -> str:
    positions = find_anagram_positions(text, pattern)
    lines = ["text=%r pattern=%r -> %d anagram substring(s)" % (text, pattern, len(positions))]
    lines.append("  " + text)
    lines.append("  " + highlight(text, positions))
    for column in range(len(positions)):
        start = positions[column]
        lines.append("  [%d] index %d: %s" % (column, start, text[start:start + len(pattern)]))
    return "\n".join(lines)


def main() -> None:
    cases = [
        ("cbaebabacd", "abc"),
        ("abab", "ab"),
        ("aaaaa", "aa"),
        ("zzz", "abc"),
    ]
    for index in range(len(cases)):
        text, pattern = cases[index]
        print(report(text, pattern))
        print()


if __name__ == "__main__":
    main()

