import sys


def split_fields(line: str) -> list[str]:
    fields: list[str] = []
    current: list[str] = []
    in_quotes = False
    skip = False
    n = len(line)
    for i in range(n):
        if skip:
            skip = False
            continue
        c = line[i]
        if c == '"':
            if in_quotes and i + 1 < n and line[i + 1] == '"':
                current.append('"')
                skip = True
            else:
                in_quotes = not in_quotes
        elif c == ',' and not in_quotes:
            fields.append(''.join(current).strip())
            current = []
        else:
            current.append(c)
    fields.append(''.join(current).strip())
    return fields


def parse_csv_columns(csv_string: str, columns: list[str]) -> list[dict[str, str]]:
    lines = []
    for raw in csv_string.replace('\r\n', '\n').replace('\r', '\n').split('\n'):
        if raw.strip():
            lines.append(raw)
    if not lines:
        return []
    headers = split_fields(lines[0])
    positions: dict[str, int] = {}
    for j in range(len(headers)):
        if headers[j] in columns and headers[j] not in positions:
            positions[headers[j]] = j
    for k in columns:
        if k not in positions:
            raise KeyError(f'column not found in header: {k!r}')
    rows: list[dict[str, str]] = []
    for i in range(1, len(lines)):
        fields = split_fields(lines[i])
        row: dict[str, str] = {}
        for k in columns:
            row[k] = fields[positions[k]] if positions[k] < len(fields) else ''
        rows.append(row)
    return rows


def column_widths(rows: list[dict[str, str]], columns: list[str]) -> list[int]:
    widths = []
    for k in columns:
        width = len(k)
        for i in range(len(rows)):
            if len(rows[i][k]) > width:
                width = len(rows[i][k])
        widths.append(width)
    return widths


def format_table(rows: list[dict[str, str]], columns: list[str]) -> str:
    widths = column_widths(rows, columns)
    out = []
    header = []
    rule = []
    for j in range(len(columns)):
        header.append(columns[j].ljust(widths[j]))
        rule.append('-' * widths[j])
    out.append(' | '.join(header))
    out.append('-+-'.join(rule))
    for i in range(len(rows)):
        cells = []
        for j in range(len(columns)):
            cells.append(rows[i][columns[j]].ljust(widths[j]))
        out.append(' | '.join(cells))
    return '\n'.join(out)


def main(argv: list[str]) -> int:
    if len(argv) < 2:
        print('usage: parse_csv.py COLUMN [COLUMN ...] < data.csv', file=sys.stderr)
        return 2
    columns = argv[1:]
    try:
        rows = parse_csv_columns(sys.stdin.read(), columns)
    except KeyError as exc:
        print(f'error: {exc.args[0]}', file=sys.stderr)
        return 1
    if rows:
        print(format_table(rows, columns))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

