def generate_spiral_matrix(n: int) -> list[list[int]]:
    """Return an n x n matrix filled with 1..n*n in clockwise spiral order."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 0:
        raise ValueError("n must be non-negative")

    matrix = [[0] * n for _ in range(n)]

    top, bottom, left, right = 0, n - 1, 0, n - 1
    value = 1
    while top <= bottom and left <= right:
        for j in range(left, right + 1):
            matrix[top][j] = value
            value += 1
        top += 1

        for i in range(top, bottom + 1):
            matrix[i][right] = value
            value += 1
        right -= 1

        if top <= bottom:
            for j in range(right, left - 1, -1):
                matrix[bottom][j] = value
                value += 1
            bottom -= 1

        if left <= right:
            for i in range(bottom, top - 1, -1):
                matrix[i][left] = value
                value += 1
            left += 1

    return matrix


def cell_width(matrix: list[list[int]]) -> int:
    """Width of the widest decimal representation in the matrix."""
    width = 1
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            length = len(str(matrix[i][j]))
            if length > width:
                width = length
    return width


def format_matrix(matrix: list[list[int]]) -> str:
    """Render a matrix as right-aligned rows of numbers."""
    width = cell_width(matrix)
    lines = []
    for i in range(len(matrix)):
        cells = []
        for j in range(len(matrix[i])):
            cells.append(str(matrix[i][j]).rjust(width))
        lines.append(" ".join(cells))
    return "\n".join(lines)


def trace(matrix: list[list[int]]) -> int:
    """Sum of the main diagonal of a square matrix."""
    total = 0
    for k in range(len(matrix)):
        total += matrix[k][k]
    return total


def main() -> None:
    for size in range(1, 6):
        spiral = generate_spiral_matrix(size)
        print("n = {}".format(size))
        print(format_matrix(spiral))
        print("trace = {}".format(trace(spiral)))
        print()


if __name__ == "__main__":
    main()

