def jaccard_index(set1: set, set2: set) -> float:
    """Return |A intersect B| / |A union B| for two sets."""
    if not isinstance(set1, (set, frozenset)) or not isinstance(set2, (set, frozenset)):
        raise TypeError("jaccard_index requires two sets")
    if not set1 and not set2:
        return 1.0
    n = 0
    for k in set1:
        if k in set2:
            n += 1
    return n / (len(set1) + len(set2) - n)


def tokenize(text: str) -> set:
    """Split text into a set of lowercase alphanumeric words."""
    cleaned = []
    for k in text.lower():
