def convert_base(decimal_num: int, base: int) -> str:
    """Return the representation of decimal_num in the given base (2..16)."""
    if not 2 <= base <= 16:
        raise ValueError("base must be between 2 and 16, got %r" % (base,))
    remaining = abs(decimal_num)
    digits = []
    while remaining:
        digits.append(DIGITS[remaining % base])
        remaining //= base
    if not digits:
        return "0"
    text = "-" if decimal_num < 0 else ""
    for i in range(len(digits) - 1, -1, -1):
        text += digits[i]
    return text


def value_of(text: str, base: int) -> int:
    """Read a string written in the given base and return its decimal value."""
    if not 2 <= base <= 16:
        raise ValueError("base must be between 2 and 16, got %r" % (base,))
    body = text.strip().upper()
    sign = 1
    if body.startswith("-"):
        sign = -1
        body = body[1:]
    if not body:
        raise ValueError("no digits to read")
    total = 0
    for i in range(len(body)):
        d = DIGITS.find(body[i])
        if d < 0 or d >= base:
            raise ValueError("%r is not a digit of base %d" % (body[i], base))
        total = total * base + d
    return sign * total


