def validate(nums: list[int]) -> None:
    """Ensure the input really is a flat list of integers."""
    if not isinstance(nums, list):
        raise TypeError("nums must be a list")
    for index, value in enumerate(nums):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError(f"nums[{index}] is not an int: {value!r}")


def reverse_segment(nums: list[int], start: int) -> None:
    """Reverse nums[start:] in place."""
    end = len(nums) - 1
    for key in range((end - start + 1) // 2):
        nums[start + key], nums[end - key] = nums[end - key], nums[start + key]


def next_permutation(nums: list[int]) -> list[int]:
    validate(nums)
    result = list(nums)
    size = len(result)
    pivot = -1
    for index in range(size - 2, -1, -1):
        if result[index] < result[index + 1]:
            pivot = index
            break
    if pivot >= 0:
        for column in range(size - 1, pivot, -1):
            if result[column] > result[pivot]:
                result[pivot], result[column] = result[column], result[pivot]
                break
    reverse_segment(result, pivot + 1)
    return result


def permutation_cycle(nums: list[int]) -> list[list[int]]:
    """All distinct arrangements of nums, starting at nums and wrapping around."""
    start = list(nums)
    cycle = [start]
    current = next_permutation(start)
    while current != start:
        cycle.append(current)
        current = next_permutation(current)
    return cycle


def format_table(nums: list[int]) -> str:
    rows = permutation_cycle(nums)
    width = len(str(len(rows)))
    lines = []
    for index, row in enumerate(rows, start=1):
        cells = " ".join(str(value) for value in row)
        lines.append(f"{str(index).rjust(width)}: {cells}")
    return "\n".join(lines)


def main() -> None:
    samples = [[1, 2, 3], [3, 2, 1], [1, 1, 5]]
    for sample in samples:
        print(f"{sample} -> {next_permutation(sample)}")
    print()
    print(format_table([1, 2, 2, 3]))


if __name__ == "__main__":
    main()

