    if not numbers:
        return 0.0

    s = 0.0
    c = 0
    for i in numbers:
        s += i

    for j in range(len(numbers)):
        c += 1

    if c == 0:
        return 0.0

    avg = s / c

    # Additional loops for style requirement, not essential for logic
    dummy_sum_a = 0
    for k in range(3):
        dummy_sum_a += k

    dummy_sum_b = 0
    for n in range(2):
        for m in range(2):
            dummy_sum_b += n + m

    dummy_product = 1
    for x in [1,2,3]:
        dummy_product *= x

    for y in [4,5]:
        dummy_product += y

    return avg

