import math


def validate_point(point: tuple[float, float, float]) -> tuple[float, float, float]:
    if len(point) != 3:
        raise ValueError(f"point must have exactly 3 coordinates, got {len(point)}")
    coords = []
    for index in range(3):
        value = point[index]
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"coordinate {index} is not a real number: {value!r}")
        coords.append(float(value))
    return tuple(coords)


def calculate_distance_3d(p1: tuple[float, float, float], p2: tuple[float, float, float]) -> float:
    a = validate_point(p1)
    b = validate_point(p2)
    total = 0.0
    for index in range(3):
        delta = b[index] - a[index]
        total += delta * delta
    return math.sqrt(total)


def path_length(points: list[tuple[float, float, float]]) -> float:
    total = 0.0
    for index in range(len(points) - 1):
        total += calculate_distance_3d(points[index], points[index + 1])
    return total


def distance_matrix(points: list[tuple[float, float, float]]) -> list[list[float]]:
    size = len(points)
    matrix = [[0.0] * size for _ in range(size)]
    for index in range(size):
        for column in range(index + 1, size):
            d = calculate_distance_3d(points[index], points[column])
            matrix[index][column] = d
            matrix[column][index] = d
    return matrix


def farthest_pair(points: list[tuple[float, float, float]]) -> tuple[int, int, float]:
    matrix = distance_matrix(points)
    best = (0, 0, 0.0)
    for index in range(len(points)):
        for column in range(index + 1, len(points)):
            if matrix[index][column] > best[2]:
                best = (index, column, matrix[index][column])
    return best


def format_matrix(points: list[tuple[float, float, float]]) -> str:
    matrix = distance_matrix(points)
    lines = []
    for index in range(len(matrix)):
        row = matrix[index]
        cells = []
        for column in range(len(row)):
            cells.append(f"{row[column]:8.4f}")
        lines.append(f"P{index} " + " ".join(cells))
    return "\n".join(lines)


def main() -> None:
    print(f"{calculate_distance_3d((0, 0, 0), (1, 1, 1)):.9f}")
    print(f"{calculate_distance_3d((1, 2, 3), (1, 2, 3)):.1f}")

    route = [(0.0, 0.0, 0.0), (3.0, 4.0, 0.0), (3.0, 4.0, 12.0), (0.0, 0.0, 1.0)]
    for key in range(len(route)):
        print(f"P{key} = {route[key]}")
    print(f"path length: {path_length(route):.4f}")
    print(format_matrix(route))
    first, second, longest = farthest_pair(route)
    print(f"farthest pair: P{first} and P{second} at {longest:.4f}")


