import calendar
import datetime


def is_weekend(date_obj: datetime.date) -> bool:
    return date_obj.weekday() >= 5


def weekend_days_in_month(year: int, month: int) -> list:
    days = calendar.monthrange(year, month)[1]
    result = []
    for i in range(1, days + 1):
        day = datetime.date(year, month, i)
        if is_weekend(day):
            result.append(day)
    return result


def count_weekends_per_month(year: int) -> list:
    counts = []
    for i in range(1, 13):
        counts.append(len(weekend_days_in_month(year, i)))
    return counts


def working_days_between(start: datetime.date, end: datetime.date) -> int:
    if end < start:
        start, end = end, start
    total = 0
    for k in range((end - start).days + 1):
        if not is_weekend(start + datetime.timedelta(days=k)):
            total += 1
    return total


def next_working_day(date_obj: datetime.date) -> datetime.date:
    candidate = date_obj + datetime.timedelta(days=1)
    while is_weekend(candidate):
        candidate += datetime.timedelta(days=1)
    return candidate


def format_month_calendar(year: int, month: int) -> str:
    weekend_set = {k.day for k in weekend_days_in_month(year, month)}
    first_weekday, days = calendar.monthrange(year, month)
    cells = [""] * first_weekday
    for i in range(1, days + 1):
        cells.append("[%2d]" % i if i in weekend_set else " %2d " % i)
    while len(cells) % 7:
        cells.append("")
    lines = ["%s %d" % (calendar.month_name[month], year)]
    for j in range(0, len(cells), 7):
        row = ""
        for k in range(7):
            row += "%-4s" % cells[j + k]
        lines.append(row.rstrip())
    return "\n".join(lines)


def main() -> None:
    samples = [datetime.date(2023, 10, 28), datetime.date(2023, 10, 26)]
    for i, day in enumerate(samples, start=1):
        print("Example %d: %s -> %s" % (i, day.isoformat(), is_weekend(day)))

    print(format_month_calendar(2023, 10))

    counts = count_weekends_per_month(2023)
    for i, count in enumerate(counts, start=1):
        print("%-10s %2d weekend days" % (calendar.month_abbr[i], count))
    print("Total weekend days in 2023: %d" % sum(counts))

    start = datetime.date(2023, 10, 1)
    end = datetime.date(2023, 10, 31)
    print("Working days in October 2023: %d" % working_days_between(start, end))

    for j in range(5):
        day = datetime.date(2023, 10, 26) + datetime.timedelta(days=j)
        print("%s -> next working day %s" % (day, next_working_day(day)))


if __name__ == "__main__":
    main()

