LABELS = ['0-10', '11-20', '21-30', '31+']
UPPER_BOUNDS = [10, 20, 30]


def bucket_label(age: int) -> str:
    """Return the age-range label that the given age belongs to."""
    for i in range(len(UPPER_BOUNDS)):
        if age <= UPPER_BOUNDS[i]:
            return LABELS[i]
    return LABELS[-1]


def validate_people(people: list[dict[str, str | int]]) -> None:
    """Raise ValueError/TypeError if any record is unusable."""
    for i in range(len(people)):
        person = people[i]
        if 'name' not in person or 'age' not in person:
            raise ValueError(f"record {i} must have 'name' and 'age' keys")
        age = person['age']
        if isinstance(age, bool) or not isinstance(age, int):
            raise TypeError(f"record {i}: age must be an int, got {age!r}")
        if age < 0:
            raise ValueError(f"record {i}: age must not be negative")


def group_by_age(people: list[dict[str, str | int]]) -> dict[str, list[str]]:
    """Group names into age-range buckets, keeping only non-empty buckets."""
    validate_people(people)
    collected: dict[str, list[str]] = {}
    for person in people:
        collected.setdefault(bucket_label(person['age']), []).append(str(person['name']))
    grouped: dict[str, list[str]] = {}
    for label in LABELS:
        if label in collected:
            grouped[label] = collected[label]
    return grouped


def sort_groups(grouped: dict[str, list[str]]) -> dict[str, list[str]]:
    """Return the same grouping with each bucket's names alphabetised."""
    return {label: sorted(names) for label, names in grouped.items()}


def count_by_range(grouped: dict[str, list[str]]) -> dict[str, int]:
    """Map each occupied range label to the number of names it holds."""
    return {label: len(names) for label, names in grouped.items()}


def busiest_range(counts: dict[str, int]) -> str:
    """Return the most populated range label, preferring the youngest on ties."""
    best = LABELS[0]
    for i in range(1, len(LABELS)):
        if counts.get(LABELS[i], 0) > counts.get(best, 0):
            best = LABELS[i]
    return best


def format_summary(counts: dict[str, int]) -> str:
    """Render one numbered table row per range with its count and share."""
    total = sum(counts.values())
    rows = []
    for i in range(len(LABELS)):
        count = counts.get(LABELS[i], 0)
        share = 100.0 * count / total if total else 0.0
        rows.append(f"{i + 1}. {LABELS[i]:<6}{count:>4}{share:8.1f}%")
    return "\n".join(rows)


def format_report(grouped: dict[str, list[str]]) -> str:
    """Render the grouping as numbered name lines, youngest range first."""
    lines = []
    for label in LABELS:
        names = grouped.get(label, [])
        if not names:
            continue
        lines.append(f"{label} ({len(names)}):")
        for j in range(len(names)):
            lines.append(f"  {j + 1}. {names[j]}")
    return "\n".join(lines)


def main() -> None:
    datasets = [
        [{'name': 'Alice', 'age': 8}, {'name': 'Bob', 'age': 25}, {'name': 'Charlie', 'age': 35}],
        [{'name': 'Eve', 'age': 15}],
        [{'name': 'Zoe', 'age': 30}, {'name': 'Ann', 'age': 11}, {'name': 'Mia', 'age': 20},
         {'name': 'Ravi', 'age': 62}, {'name': 'Tom', 'age': 0}],
    ]
    for k in range(len(datasets)):
        grouped = sort_groups(group_by_age(datasets[k]))
        counts = count_by_range(grouped)
        print(f"Dataset {k + 1} — {sum(counts.values())} people in {len(grouped)} range(s)")
        print(f"busiest range: {busiest_range(counts)}")
        print(format_summary(counts))
        print(format_report(grouped))
        print()


if __name__ == '__main__':
    main()

