FEET_TO_METERS = 0.3048


def feet_to_meters(feet: float) -> float:
    """Convert a length given in feet to meters."""
    return feet * FEET_TO_METERS


def parse_feet_values(text: str) -> list:
    """Read a comma/space separated list of feet values into floats."""
    tokens = text.replace(",", " ").split()
    values = []
    for i, token in enumerate(tokens):
        try:
            values.append(float(token))
        except ValueError:
            raise ValueError("value %d is not a number: %r" % (i + 1, token))
    return values


def build_rows(values: list) -> list:
    """Build a table (header plus one row per value) of the conversions."""
    rows = [["feet", "meters", "centimeters"]]
    for value in values:
        meters = feet_to_meters(value)
        rows.append(["%.4f" % value, "%.4f" % meters, "%.2f" % (meters * 100.0)])
    return rows


def format_table(rows: list) -> list:
    """Render rows as aligned text lines, with a rule under the header."""
    cols = max(len(row) for row in rows)
    widths = [0] * cols
    for row in rows:
        for j, cell in enumerate(row):
            widths[j] = max(widths[j], len(cell))
    lines = []
    for i, row in enumerate(rows):
        cells = [row[j].rjust(widths[j]) for j in range(len(row))]
        lines.append(" | ".join(cells))
        if i == 0:
            lines.append("-+-".join("-" * widths[k] for k in range(cols)))
    return lines


def main() -> None:
    raw = "10, 0, 5.5, 3.2808, 100, 1"
    values = parse_feet_values(raw)

    for line in format_table(build_rows(values)):
        print(line)

    total_feet = sum(values)
    print()
    print("total: %.4f ft = %.4f m" % (total_feet, feet_to_meters(total_feet)))
    print("longest: %.4f ft = %.4f m" % (max(values), feet_to_meters(max(values))))


if __name__ == "__main__":
    main()

