def validate_inventory(items):
    """Check that the inventory is a list of {'name': str, 'stock': int} records."""
    if not isinstance(items, list):
        raise TypeError("inventory must be a list of dictionaries")
    for i in range(len(items)):
        item = items[i]
        if not isinstance(item, dict):
            raise TypeError("inventory entry %d is not a dictionary" % i)
        for k in ("name", "stock"):
            if k not in item:
                raise KeyError("inventory entry %d is missing the '%s' key" % (i, k))
        if not isinstance(item["name"], str) or not item["name"]:
            raise ValueError("inventory entry %d has an invalid name" % i)
        if not isinstance(item["stock"], int) or isinstance(item["stock"], bool):
            raise TypeError("stock of '%s' must be an integer" % item["name"])
        if item["stock"] < 0:
            raise ValueError("stock of '%s' cannot be negative" % item["name"])
    return items


def find_low_stock_items(items, threshold):
    """Return the names of all items whose stock is at or below the threshold."""
    validate_inventory(items)
    low = []
    for i in range(len(items)):
        if items[i]["stock"] <= threshold:
            low.append(items[i]["name"])
    return low


def stock_levels(items):
    """Collapse the inventory into a name -> total stock mapping."""
    levels = {}
    for j in range(len(items)):
        name = items[j]["name"]
        levels[name] = levels.get(name, 0) + items[j]["stock"]
    return levels


def suggest_restock_orders(items, threshold, target):
    """Pair each low-stock name with the quantity needed to reach the target."""
    levels = stock_levels(items)
    names = find_low_stock_items(items, threshold)
    orders = []
    for k in range(len(names)):
        missing = target - levels[names[k]]
        if missing > 0:
            orders.append((names[k], missing))
    return orders


def format_report(names, levels):
    """Build aligned 'name  stock' lines for the given names."""
    width = max((len(name) for name in names), default=0)
    lines = []
    for i in range(len(names)):
        lines.append("%s  %3d" % (names[i].ljust(width), levels[names[i]]))
    return lines


def main():
    inventory = [
        {"name": "bolts", "stock": 5},
        {"name": "nuts", "stock": 12},
        {"name": "washers", "stock": 0},
        {"name": "screws", "stock": 4},
        {"name": "bolts", "stock": 2},
    ]
    threshold = 5
    low = find_low_stock_items(inventory, threshold)
    print("Items at or below %d units:" % threshold)
    for line in format_report(low, stock_levels(inventory)):
        print("  " + line)

    orders = suggest_restock_orders(inventory, threshold, target=20)
    total = 0
    for j in range(len(orders)):
        print("  order %d x %s" % (orders[j][1], orders[j][0]))
        total += orders[j][1]
    print("Total units to order: %d" % total)


if __name__ == "__main__":
    main()

