def split_words(text):
    """Split a space separated string into its words."""
    if text == '':
        return []
    words = []
    start = 0
    for index in range(len(text)):
        if text[index] == ' ':
            words.append(text[start:index])
            start = index + 1
    words.append(text[start:])
    return words


def join_words(words):
    """Join words back together with single spaces."""
    out = ''
    for column in range(len(words)):
        if column > 0:
            out += ' '
        out += words[column]
    return out


