        cleaned.append(name)
    for i in range(len(cleaned)):
        for j in range(i + 1, len(cleaned)):
            if cleaned[i] == cleaned[j]:
                raise ValueError("duplicate flag name: %r" % (cleaned[i],))
    return cleaned


def split_args(argv):
    """Split argv into (flag names without '--', positional arguments).

    Everything following a bare '--' is treated as positional.
    """
    end = len(argv)
    for i in range(len(argv)):
        if argv[i] == "--":
            end = i
            break
    flags = []
    positionals = []
    for j in range(end):
        token = argv[j]
        if token.startswith("--") and len(token) > 2:
            flags.append(token[2:])
        else:
            positionals.append(token)
    for k in range(end + 1, len(argv)):
        positionals.append(argv[k])
    return flags, positionals


