import random
from collections import Counter

RANKS = ['Ace', '2', '3', '4', '5', '6', '7', '8', '9', '10', 'Jack', 'Queen', 'King']
SUITS = ['Clubs', 'Diamonds', 'Hearts', 'Spades']


def build_deck():
    """Return a fresh, ordered list of the 52 standard cards."""
    deck = []
    for suit in SUITS:
        for rank in RANKS:
            deck.append(rank + ' of ' + suit)
    return deck


def draw_card():
    """Draw one random card from a fresh 52-card deck."""
    return random.choice(build_deck())


def draw_hand(size):
    """Draw `size` cards, each from its own fresh deck (draws may repeat)."""
    hand = []
    for i in range(size):
        hand.append(draw_card())
    return hand


def deal(players, size):
    """Deal one hand of `size` cards to each of `players` players."""
    hands = []
    for i in range(players):
        hands.append(draw_hand(size))
    return hands


def card_value(card):
    """Blackjack-style value of a card name: Ace is 11, face cards 10."""
    rank = card.split(' of ')[0]
    if rank == 'Ace':
        return 11
    if rank in ('Jack', 'Queen', 'King'):
        return 10
    return int(rank)


def hand_value(hand):
    return sum(card_value(card) for card in hand)


def suit_tally(cards):
    """Count how many drawn cards belong to each suit."""
    tally = Counter()
    for card in cards:
        tally[card.split(' of ')[1]] += 1
    return tally


def rank_frequencies(trials):
    """Tally the ranks seen over `trials` independent single-card draws."""
    counts = Counter()
    for k in range(trials):
        counts[draw_card().split(' of ')[0]] += 1
    return counts


def format_report(hands):
    """Build a printable listing of the dealt hands with values and suit totals."""
    lines = []
    dealt = []
    for i, hand in enumerate(hands, 1):
        lines.append('Player {}:'.format(i))
        for j, card in enumerate(hand, 1):
            lines.append('  {:>2}. {:<18} value {:>2}'.format(j, card, card_value(card)))
        lines.append('  hand value: {}'.format(hand_value(hand)))
        dealt.extend(hand)
    lines.append('-' * 32)
    tally = suit_tally(dealt)
    for suit in SUITS:
        lines.append('{:<10} {}'.format(suit + ':', tally[suit]))
    return '\n'.join(lines)


def main():
    print('deck size:', len(build_deck()))
    print('single draw:', draw_card())
    print()
    print(format_report(deal(3, 5)))
    print()
    counts = rank_frequencies(1300)
    print('rank frequencies over 1300 draws:')
    for rank in RANKS:
        print('{:<6} {}'.format(rank, counts[rank]))


if __name__ == '__main__':
    main()

