def split_into_chunks(items, chunk_size):
    """Split `items` into consecutive lists of length `chunk_size`."""
    if not isinstance(chunk_size, int) or isinstance(chunk_size, bool):
        raise TypeError("chunk_size must be an integer")
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    data = list(items)
    chunks = []
    for i in range(0, len(data), chunk_size):
        chunk = []
        for j in range(i, min(i + chunk_size, len(data))):
            chunk.append(data[j])
        chunks.append(chunk)
    return chunks


def pad_last_chunk(chunks, chunk_size, fill=None):
    """Return a copy of `chunks` where the final chunk is filled up to size."""
    padded = []
    for i in range(len(chunks)):
        padded.append(list(chunks[i]))
    if padded:
        last = padded[-1]
        for i in range(chunk_size - len(last)):
            last.append(fill)
    return padded


def column_widths(chunks):
    """Width in characters needed by each column position of the chunks."""
    widest = 0
    for i in range(len(chunks)):
        if len(chunks[i]) > widest:
            widest = len(chunks[i])
    widths = [0] * widest
    for i in range(len(chunks)):
        for j in range(len(chunks[i])):
            size = len(repr(chunks[i][j]))
            if size > widths[j]:
                widths[j] = size
    return widths


def format_chunks(chunks):
    """Render the chunks as an aligned, numbered text table."""
    widths = column_widths(chunks)
    lines = []
    for i in range(len(chunks)):
        cells = []
        for j in range(len(chunks[i])):
            cells.append(repr(chunks[i][j]).rjust(widths[j]))
        lines.append("chunk %d: %s" % (i, "  ".join(cells)))
    return "\n".join(lines)


def main():
    samples = [([1, 2, 3, 4, 5, 6, 7], 3), (['a', 'b', 'c', 'd'], 2),
               (list(range(11)), 4), ([], 5)]
    for i in range(len(samples)):
        items, size = samples[i]
        chunks = split_into_chunks(items, size)
        print("input %r with chunk_size %d -> %r" % (items, size, chunks))
        if chunks:
            print(format_chunks(chunks))
            print("padded: %r" % (pad_last_chunk(chunks, size, fill=0),))
        print()


if __name__ == "__main__":
