import random

HEX_DIGITS = "0123456789ABCDEF"


def generate_random_hex_color():
    """Return a random color as a '#RRGGBB' string."""
    value = random.randrange(0x1000000)
    digits = []
    for i in range(6):
        digits.append(HEX_DIGITS[(value >> (4 * (5 - i))) & 0xF])
    return "#" + "".join(digits)


def is_valid_hex_color(code):
    """Check that code looks like '#RRGGBB' with uppercase hex digits."""
    if not isinstance(code, str) or len(code) != 7 or code[0] != "#":
        return False
    for i in range(1, 7):
        if code[i] not in HEX_DIGITS:
            return False
    return True


def to_rgb(code):
    """Split a valid '#RRGGBB' string into an (r, g, b) tuple."""
    if not is_valid_hex_color(code):
        raise ValueError("not a hex color: %r" % (code,))
    channels = []
    for i in range(3):
        pair = code[1 + 2 * i:3 + 2 * i]
        value = 0
        for j in range(2):
            value = value * 16 + HEX_DIGITS.index(pair[j])
        channels.append(value)
    return tuple(channels)


def brightness(code):
    """Perceived brightness of a color, 0.0 (black) to 1.0 (white)."""
    weights = (0.299, 0.587, 0.114)
    rgb = to_rgb(code)
    total = 0.0
    for i in range(3):
        total += weights[i] * rgb[i]
    return total / 255.0


def generate_palette(size, min_brightness=0.0):
    """Return `size` distinct colors, each at least `min_brightness` bright."""
    if size < 1:
        raise ValueError("palette size must be positive")
    palette = []
    while len(palette) < size:
        color = generate_random_hex_color()
        if brightness(color) >= min_brightness and color not in palette:
            palette.append(color)
    return palette


def format_palette(palette):
    """Render a palette as aligned lines of code, RGB and brightness."""
    lines = []
    for i in range(len(palette)):
        color = palette[i]
        r, g, b = to_rgb(color)
        lines.append("%2d. %s  rgb(%3d, %3d, %3d)  brightness %.2f"
                     % (i + 1, color, r, g, b, brightness(color)))
    return "\n".join(lines)


def main():
    print("single color:", generate_random_hex_color())
    palette = generate_palette(8, min_brightness=0.35)
    print(format_palette(palette))
    channel_names = ("red", "green", "blue")
    sums = [0, 0, 0]
    for color in palette:
        rgb = to_rgb(color)
        for k in range(3):
            sums[k] += rgb[k]
    for k in range(3):
        print("average %-5s %6.1f" % (channel_names[k], sums[k] / len(palette)))


if __name__ == "__main__":
    main()

