def has_duplicates(s):
    """Return True if the string contains at least one repeated character."""
    if not isinstance(s, str):
        raise TypeError("has_duplicates() expects a string")
    seen = set()
    for i in range(len(s)):
        c = s[i]
        if c in seen:
            return True
        seen.add(c)
    return False


def character_counts(s):
    """Map every character of s to the number of times it occurs."""
    counts = {}
    for j in range(len(s)):
        c = s[j]
        counts[c] = counts.get(c, 0) + 1
    return counts


def duplicate_characters(s):
    """List the repeated characters, in order of their first appearance."""
    counts = character_counts(s)
    dups = []
    for k in range(len(s)):
        c = s[k]
        if counts[c] > 1 and c not in dups:
            dups.append(c)
    return dups


def longest_unique_prefix(s):
    """Return the longest leading part of s whose characters are all distinct."""
    for i in range(len(s)):
        if s[i] in s[:i]:
            return s[:i]
    return s


def describe(s):
    """Build a one-line human readable verdict for a single string."""
    dups = duplicate_characters(s)
    if not dups:
        return "%-12s no duplicates" % repr(s)
    counts = character_counts(s)
    parts = []
    for j in range(len(dups)):
        c = dups[j]
        parts.append("%s x%d" % (repr(c), counts[c]))
    return "%-12s duplicates: %s (unique prefix %s)" % (
        repr(s), ", ".join(parts), repr(longest_unique_prefix(s)))


def report(strings):
    """Print a verdict for each string plus a summary count."""
    affected = 0
    for k in range(len(strings)):
        s = strings[k]
        if has_duplicates(s):
            affected += 1
        print("%2d. %s" % (k + 1, describe(s)))
    print("%d of %d string(s) contain duplicate characters."
          % (affected, len(strings)))
    return affected


def main():
    samples = ["hello", "abcdefg", "", "a", "mississippi", "Aa", "abcabc"]
    report(samples)


if __name__ == "__main__":
    main()

