    ys = sorted({box[1] for box in boxes} | {box[3] for box in boxes})
    area = 0.0
    for index in range(len(xs) - 1):
        for column in range(len(ys) - 1):
            cx = (xs[index] + xs[index + 1]) / 2.0
            cy = (ys[column] + ys[column + 1]) / 2.0
            for bx1, by1, bx2, by2 in boxes:
                if bx1 <= cx <= bx2 and by1 <= cy <= by2:
                    area += (xs[index + 1] - xs[index]) * (ys[column + 1] - ys[column])
                    break
    return area


def report(rects):
    matrix = overlap_matrix(rects)
    lines = []
    for index in range(len(rects)):
        lines.append("R%d = (%g, %g) .. (%g, %g)" % (index, *rects[index]))
    for index in range(len(matrix)):
        cells = []
        for column in range(len(matrix[index])):
            cells.append("%8.3f" % matrix[index][column])
        lines.append("R%d |%s" % (index, " ".join(cells)))
    lines.append("sum of pairwise overlaps: %.3f" % total_pairwise_overlap(rects))
    lines.append("area of union: %.3f" % union_area(rects))
    return "\n".join(lines)


