def validate_headers(headers):
    """Check that headers is a usable list of distinct, non-empty names."""
    if not isinstance(headers, list):
        raise TypeError('headers must be a list of strings')
    for i in range(len(headers)):
        if not isinstance(headers[i], str):
            raise TypeError('header at position %d is not a string' % i)
        if headers[i] == '':
            raise ValueError('header at position %d is empty' % i)
        for j in range(i + 1, len(headers)):
            if headers[j] == headers[i]:
                raise ValueError('duplicate header %r' % headers[i])
    return headers


def split_fields(line):
    """Split a CSV line on commas; no quoting or escaping is supported."""
    fields = []
    start = 0
    for k in range(len(line)):
        if line[k] == ',':
            fields.append(line[start:k])
            start = k + 1
    fields.append(line[start:])
    return fields


def parse_csv_line_to_dict(line, headers):
    """Map the comma-separated values of `line` onto `headers`."""
    validate_headers(headers)
    fields = split_fields(line)
    if len(fields) != len(headers):
        raise ValueError('expected %d fields, got %d' % (len(headers), len(fields)))
    record = {}
    for i in range(len(headers)):
        record[headers[i]] = fields[i]
    return record


def parse_csv_text(text, headers):
    """Parse every non-empty line of `text` into a record dictionary."""
    records = []
    lines = text.splitlines()
    for i in range(len(lines)):
        if lines[i].strip() == '':
            continue
        records.append(parse_csv_line_to_dict(lines[i], headers))
    return records


def column_widths(records, headers):
    """Width of each column: the longest of its header and its values."""
    widths = []
    for j in range(len(headers)):
        width = len(headers[j])
        for k in range(len(records)):
            value = records[k][headers[j]]
            if len(value) > width:
                width = len(value)
        widths.append(width)
    return widths


def format_table(records, headers):
    """Render parsed records as an aligned, pipe-separated text table."""
    widths = column_widths(records, headers)
    header_cells = []
    rule_cells = []
    for j in range(len(headers)):
        header_cells.append(headers[j].ljust(widths[j]))
        rule_cells.append('-' * widths[j])
    rows = [' | '.join(header_cells), '-+-'.join(rule_cells)]
    for i in range(len(records)):
        cells = []
        for j in range(len(headers)):
            cells.append(records[i][headers[j]].ljust(widths[j]))
        rows.append(' | '.join(cells))
    return '\n'.join(rows)


def main():
    print(parse_csv_line_to_dict('John,Doe,30', ['first_name', 'last_name', 'age']))
