    text = 'John,Doe,30\nJane,Roe,41\n\nSam,Smith,7\n'
    people = parse_csv_text(text, ['first_name', 'last_name', 'age'])
    print(format_table(people, ['first_name', 'last_name', 'age']))


if __name__ == '__main__':
