                raise ValueError("bad cell at (%d, %d): %r" % (i, j, row[j]))


def validate_player(player):
    if player not in ('X', 'O'):
        raise ValueError("player must be 'X' or 'O', got %r" % (player,))


def check_tic_tac_toe_win_rc(board, player):
    validate_board(board)
    validate_player(player)
    for i in range(3):
        full = True
        for j in range(3):
            if board[i][j] != player:
                full = False
        if full:
            return True
    for j in range(3):
        full = True
        for i in range(3):
            if board[i][j] != player:
                full = False
        if full:
            return True
