import random
from collections import Counter


def generate_random_pin():
    digits = []
    for i in range(4):
        digits.append(str(random.randint(0, 9)))
    return "".join(digits)


def generate_unique_pins(count):
    pins = set()
    while len(pins) < count:
        pins.add(generate_random_pin())
    return sorted(pins)


def is_valid_pin(pin):
    if not isinstance(pin, str) or len(pin) != 4:
        return False
    for i in range(len(pin)):
        if pin[i] not in "0123456789":
            return False
    return True


def digit_frequency(pins):
    counter = Counter()
    for i in range(len(pins)):
        for j in range(4):
            counter[pins[i][j]] += 1
    return counter


def has_repeated_digit(pin):
    for i in range(len(pin)):
        for j in range(i + 1, len(pin)):
            if pin[i] == pin[j]:
                return True
    return False


def longest_ascending_run(pin):
    best = 1
    run = 1
    for k in range(1, len(pin)):
        if int(pin[k]) == int(pin[k - 1]) + 1:
            run += 1
            if run > best:
                best = run
        else:
            run = 1
    return best


def format_report(pins):
    lines = []
    for i in range(len(pins)):
        pin = pins[i]
        flags = []
        if has_repeated_digit(pin):
            flags.append("repeat")
        if longest_ascending_run(pin) >= 3:
            flags.append("sequence")
        note = ", ".join(flags) if flags else "ok"
        lines.append("%3d. %s  [%s]" % (i + 1, pin, note))
    freq = digit_frequency(pins)
    lines.append("")
    lines.append("digit counts:")
    for j in range(10):
        lines.append("  %d -> %d" % (j, freq[str(j)]))
    return "\n".join(lines)


def main():
    batch = generate_unique_pins(12)
    for i in range(len(batch)):
        if not is_valid_pin(batch[i]):
            raise ValueError("generated invalid pin: %r" % batch[i])
    print(format_report(batch))


if __name__ == "__main__":
    main()

